window.FG_SHARED_KNOWLEDGE=[{"kind":"article","id":"100-prozent-finanzierung","title":"100-Prozent-Finanzierung","category":"Finanzierung","summary":"Bei einer 100-Prozent-Finanzierung wird regelmäßig der Kaufpreis finanziert, nicht automatisch jede Nebenkostenposition.","answer":"Bei einer 100-Prozent-Finanzierung wird regelmäßig der Kaufpreis finanziert, nicht automatisch jede Nebenkostenposition. 100 % bezieht sich in der Praxis regelmäßig auf den Kaufpreis. Grunderwerbsteuer, Notar, Grundbuch und gegebenenfalls Courtage sind damit nicht automatisch finanziert.","url":"/wissen/100-prozent-finanzierung/","keywords":["100-prozent-finanzierung","regelmäßig","kaufpreis","finanziert","automatisch","jede","nebenkostenposition","100","bezieht","praxis","grunderwerbsteuer","notar","grundbuch","gegebenenfalls","courtage","damit"]},{"kind":"article","id":"110-prozent-finanzierung","title":"110-Prozent-Finanzierung","category":"Finanzierung","summary":"Werden Kaufpreis und Nebenkosten finanziert, liegt das Darlehen über dem Kaufpreis.","answer":"Werden Kaufpreis und Nebenkosten finanziert, liegt das Darlehen über dem Kaufpreis. Bei einer 110-%-Finanzierung werden neben dem Kaufpreis auch Erwerbsnebenkosten ganz oder teilweise fremdfinanziert. Dadurch liegt die Darlehenssumme oberhalb des Kaufpreises.","url":"/wissen/110-prozent-finanzierung/","keywords":["110-prozent-finanzierung","kaufpreis","nebenkosten","finanziert","liegt","darlehen","über","110-%-finanzierung","neben","erwerbsnebenkosten","ganz","teilweise","fremdfinanziert","dadurch","darlehenssumme","oberhalb","kaufpreises"]},{"kind":"article","id":"5-afa-wann-ist-sie-moglich","title":"5 % AfA – wann ist sie möglich?","category":"Steuern","summary":"Erhöhte Abschreibungssätze gelten nur bei bestimmten gesetzlichen Voraussetzungen.","answer":"Erhöhte Abschreibungssätze gelten nur bei bestimmten gesetzlichen Voraussetzungen. Die Aussage „5 % AfA“ kann drei verschiedene Dinge vermischen: degressive Gebäude-AfA, § 7b-Sonderabschreibung und individuelle AfA bei nachgewiesener kürzerer tatsächlicher Nutzungsdauer.","url":"/wissen/5-afa-wann-ist-sie-moglich/","keywords":["afa","wann","sie","möglich","erhöhte","abschreibungssätze","gelten","nur","bestimmten","gesetzlichen","voraussetzungen","aussage","drei","verschiedene","dinge","vermischen","degressive","gebäude-afa","7b-sonderabschreibung","individuelle","nachgewiesener","kürzerer","tatsächlicher","nutzungsdauer"]},{"kind":"article","id":"afa-richtig-berechnen","title":"AfA richtig berechnen","category":"Steuern","summary":"Die Abschreibung bezieht sich grundsätzlich auf den abschreibungsfähigen Gebäudeanteil, nicht auf den Bodenwert.","answer":"Die Abschreibung bezieht sich grundsätzlich auf den abschreibungsfähigen Gebäudeanteil, nicht auf den Bodenwert. Abschreibbar ist bei Grundstückskäufen nur der Gebäudeanteil der Anschaffungskosten. Grund und Boden unterliegt keinem planmäßigen Werteverzehr und gehört daher nicht in die AfA-Bemessungsgrundlage.","url":"/wissen/afa-richtig-berechnen/","keywords":["afa","richtig","berechnen","abschreibung","bezieht","grundsätzlich","abschreibungsfähigen","gebäudeanteil","bodenwert","abschreibbar","grundstückskäufen","nur","anschaffungskosten","grund","boden","unterliegt","keinem","planmäßigen","werteverzehr","gehört","daher","afa-bemessungsgrundlage"]},{"kind":"article","id":"annuitatendarlehen-erklart","title":"Annuitätendarlehen erklärt","category":"Finanzierung","summary":"Beim Annuitätendarlehen bleibt die Rate während der Zinsbindung regelmäßig konstant.","answer":"Beim Annuitätendarlehen bleibt die Rate während der Zinsbindung regelmäßig konstant. Die Annuität ist die während der Zinsbindung typischerweise konstante Rate aus Zins und Tilgung. Weil der Zins auf die jeweils verbleibende Restschuld berechnet wird, sinkt der Zinsanteil im Zeitverlauf und der Tilgungsanteil steigt.","url":"/wissen/annuitatendarlehen-erklart/","keywords":["annuitätendarlehen","erklärt","beim","bleibt","rate","während","zinsbindung","regelmäßig","konstant","annuität","typischerweise","konstante","aus","zins","tilgung","weil","jeweils","verbleibende","restschuld","berechnet","sinkt","zinsanteil","zeitverlauf","tilgungsanteil","steigt"]},{"kind":"article","id":"anschlussfinanzierung-planen","title":"Anschlussfinanzierung planen","category":"Finanzierung","summary":"Entscheidend sind Restschuld, künftiger Zins und verbleibende Laufzeit.","answer":"Entscheidend sind Restschuld, künftiger Zins und verbleibende Laufzeit. Die Anschlussfinanzierung betrifft die Restschuld nach Ende der Sollzinsbindung. Entscheidend ist daher nicht der ursprüngliche Kaufpreis, sondern die zu diesem Zeitpunkt verbleibende Darlehenssumme.","url":"/wissen/anschlussfinanzierung-planen/","keywords":["anschlussfinanzierung","planen","entscheidend","restschuld","künftiger","zins","verbleibende","laufzeit","betrifft","nach","ende","sollzinsbindung","daher","ursprüngliche","kaufpreis","sondern","diesem","zeitpunkt","darlehenssumme"]},{"kind":"article","id":"beleihungsauslauf-und-kondition","title":"Beleihungsauslauf und Kondition","category":"Finanzierung","summary":"Der Beleihungsauslauf setzt das Darlehen ins Verhältnis zum bankseitigen Beleihungswert.","answer":"Der Beleihungsauslauf setzt das Darlehen ins Verhältnis zum bankseitigen Beleihungswert. Der Beleihungsauslauf setzt die Darlehenssumme ins Verhältnis zum bankinternen Beleihungswert, nicht zwingend zum Kaufpreis. Deshalb kann er höher sein als die einfache Kaufpreisfinanzierungsquote.","url":"/wissen/beleihungsauslauf-und-kondition/","keywords":["beleihungsauslauf","kondition","setzt","darlehen","ins","verhältnis","zum","bankseitigen","beleihungswert","darlehenssumme","bankinternen","zwingend","kaufpreis","deshalb","höher","sein","einfache","kaufpreisfinanzierungsquote"]},{"kind":"article","id":"bereitstellungszinsen","title":"Bereitstellungszinsen","category":"Finanzierung","summary":"Nicht abgerufene Darlehensteile können nach einer bereitstellungsfreien Zeit Kosten verursachen.","answer":"Nicht abgerufene Darlehensteile können nach einer bereitstellungsfreien Zeit Kosten verursachen. Bereitstellungszinsen entstehen, wenn zugesagte Darlehensteile nach Ablauf einer bereitstellungszinsfreien Zeit noch nicht abgerufen wurden. Das ist besonders bei Neubau, Bauträgerzahlungen und Sanierungen relevant.","url":"/wissen/bereitstellungszinsen/","keywords":["bereitstellungszinsen","abgerufene","darlehensteile","können","nach","bereitstellungsfreien","zeit","kosten","verursachen","entstehen","wenn","zugesagte","ablauf","bereitstellungszinsfreien","noch","abgerufen","wurden","besonders","neubau","bauträgerzahlungen","sanierungen","relevant"]},{"kind":"article","id":"bodenrichtwert-richtig-lesen","title":"Bodenrichtwert richtig lesen","category":"Marktanalysen","summary":"Der Bodenrichtwert ist ein durchschnittlicher Lagewert für ein definiertes Gebiet.","answer":"Der Bodenrichtwert ist ein durchschnittlicher Lagewert für ein definiertes Gebiet. Der Bodenrichtwert ist ein durchschnittlicher Lagewert für den Boden innerhalb einer Bodenrichtwertzone und kein verbindlicher Einzelgrundstückspreis.","url":"/wissen/bodenrichtwert-richtig-lesen/","keywords":["bodenrichtwert","richtig","lesen","ein","durchschnittlicher","lagewert","definiertes","gebiet","boden","innerhalb","bodenrichtwertzone","kein","verbindlicher","einzelgrundstückspreis"]},{"kind":"article","id":"brutto-vs-nettomietrendite","title":"Brutto- vs. Nettomietrendite","category":"Kapitalanlage","summary":"Die Bruttorendite teilt Jahresnettokaltmiete durch Kaufpreis. Die Nettorendite berücksichtigt laufende Eigentümerkosten.","answer":"Die Bruttorendite teilt Jahresnettokaltmiete durch Kaufpreis. Die Nettorendite berücksichtigt laufende Eigentümerkosten. Die Bruttomietrendite setzt Jahresnettokaltmiete ins Verhältnis zum Kaufpreis und ignoriert Erwerbsnebenkosten sowie laufende Eigentümerkosten.","url":"/wissen/brutto-vs-nettomietrendite/","keywords":["brutto-","nettomietrendite","bruttorendite","teilt","jahresnettokaltmiete","durch","kaufpreis","nettorendite","berücksichtigt","laufende","eigentümerkosten","bruttomietrendite","setzt","ins","verhältnis","zum","ignoriert","erwerbsnebenkosten","sowie"]},{"kind":"article","id":"bruttogeschossflache-vs-wohnflache","title":"Bruttogeschossfläche vs. Wohnfläche","category":"Immobilienkauf","summary":"Flächenbegriffe sind nicht austauschbar.","answer":"Flächenbegriffe sind nicht austauschbar. Bruttogrund-/Geschossflächen und Wohnfläche beruhen auf unterschiedlichen Definitionen und dürfen nicht für €/m²-Vergleiche vermischt werden.","url":"/wissen/bruttogeschossflache-vs-wohnflache/","keywords":["bruttogeschossfläche","wohnfläche","flächenbegriffe","austauschbar","bruttogrund-","geschossflächen","beruhen","unterschiedlichen","definitionen","dürfen","-vergleiche","vermischt"]},{"kind":"article","id":"capex-statt-schonrechnung","title":"Capex statt Schönrechnung","category":"Kapitalanlage","summary":"Größere Investitionen gehören getrennt von laufenden Kosten in die Planung.","answer":"Größere Investitionen gehören getrennt von laufenden Kosten in die Planung. CapEx sind größere, unregelmäßige Investitionen in die Substanz, etwa Dach, Fassade, Heizung, Leitungen oder Fenster. Sie verschwinden nicht dadurch, dass sie nicht jährlich anfallen.","url":"/wissen/capex-statt-schonrechnung/","keywords":["capex","statt","schönrechnung","größere","investitionen","gehören","getrennt","laufenden","kosten","planung","unregelmäßige","substanz","etwa","dach","fassade","heizung","leitungen","fenster","sie","verschwinden","dadurch","dass","jährlich","anfallen"]},{"kind":"article","id":"cashflow-verstehen","title":"Cashflow verstehen","category":"Kapitalanlage","summary":"Cashflow zeigt, welcher laufende Überschuss oder Zuschuss nach Miete, Kosten und Finanzierung verbleibt.","answer":"Cashflow zeigt, welcher laufende Überschuss oder Zuschuss nach Miete, Kosten und Finanzierung verbleibt. Cashflow misst Zahlungsströme, nicht steuerlichen Gewinn und nicht automatisch Vermögensaufbau. Tilgung ist Liquiditätsabfluss, erhöht aber gleichzeitig das Eigenkapital im Objekt.","url":"/wissen/cashflow-verstehen/","keywords":["cashflow","verstehen","zeigt","welcher","laufende","überschuss","zuschuss","nach","miete","kosten","finanzierung","verbleibt","misst","zahlungsströme","steuerlichen","gewinn","automatisch","vermögensaufbau","tilgung","liquiditätsabfluss","erhöht","aber","gleichzeitig","eigenkapital","objekt"]},{"kind":"article","id":"deal-screening-in-funf-minuten","title":"Deal-Screening in fünf Minuten","category":"Kapitalanlage","summary":"Ein schneller Check nutzt Kaufpreis, Jahresmiete, nicht umlagefähige Kosten, Zins und Tilgung.","answer":"Ein schneller Check nutzt Kaufpreis, Jahresmiete, nicht umlagefähige Kosten, Zins und Tilgung. Ein Schnell-Screening soll schlechte Deals früh aussortieren, nicht die Due Diligence ersetzen. Es arbeitet deshalb mit wenigen harten Größen: Gesamtinvestition, JNKM, nicht umlagefähige Kosten, CapEx, Finanzierung und realistische Marktmiete.","url":"/wissen/deal-screening-in-funf-minuten/","keywords":["deal-screening","fünf","minuten","ein","schneller","check","nutzt","kaufpreis","jahresmiete","umlagefähige","kosten","zins","tilgung","schnell-screening","soll","schlechte","deals","früh","aussortieren","due","diligence","ersetzen","arbeitet","deshalb","wenigen","harten","größen","gesamtinvestition","jnkm","capex"]},{"kind":"article","id":"dscr-verstehen","title":"DSCR verstehen","category":"Finanzierung","summary":"Der Debt Service Coverage Ratio vergleicht verfügbaren Objektüberschuss mit dem Schuldendienst.","answer":"Der Debt Service Coverage Ratio vergleicht verfügbaren Objektüberschuss mit dem Schuldendienst. Der Debt Service Coverage Ratio setzt einen definierten verfügbaren Ertrag ins Verhältnis zum Kapitaldienst. Bei 1,0 reicht der betrachtete Ertrag rechnerisch gerade für Zins und Tilgung.","url":"/wissen/dscr-verstehen/","keywords":["dscr","verstehen","debt","service","coverage","ratio","vergleicht","verfügbaren","objektüberschuss","schuldendienst","setzt","einen","definierten","ertrag","ins","verhältnis","zum","kapitaldienst","reicht","betrachtete","rechnerisch","gerade","zins","tilgung"]},{"kind":"article","id":"due-diligence-fur-einsteiger","title":"Due Diligence für Einsteiger","category":"Immobilienkauf","summary":"Eine strukturierte Prüfung umfasst Recht, Technik, Miete, Markt, Finanzierung und Steuern.","answer":"Eine strukturierte Prüfung umfasst Recht, Technik, Miete, Markt, Finanzierung und Steuern. Due Diligence verbindet rechtliche, technische, wirtschaftliche und finanzielle Prüfung. Eine gute Renditekennzahl kann einen ungeklärten Grundbuchvermerk oder Sanierungsstau nicht kompensieren.","url":"/wissen/due-diligence-fur-einsteiger/","keywords":["due","diligence","einsteiger","strukturierte","prüfung","umfasst","recht","technik","miete","markt","finanzierung","steuern","verbindet","rechtliche","technische","wirtschaftliche","finanzielle","gute","renditekennzahl","einen","ungeklärten","grundbuchvermerk","sanierungsstau","kompensieren"]},{"kind":"article","id":"eigenkapital-optimal-einsetzen","title":"Eigenkapital optimal einsetzen","category":"Finanzierung","summary":"Mehr Eigenkapital senkt Darlehen und Risiko, kann aber die prozentuale Eigenkapitalrendite reduzieren.","answer":"Mehr Eigenkapital senkt Darlehen und Risiko, kann aber die prozentuale Eigenkapitalrendite reduzieren. Mehr Eigenkapital reduziert Darlehenssumme und häufig den Beleihungsauslauf. Dadurch können sich sowohl Rate als auch Bankkondition verbessern.","url":"/wissen/eigenkapital-optimal-einsetzen/","keywords":["eigenkapital","optimal","einsetzen","mehr","senkt","darlehen","risiko","aber","prozentuale","eigenkapitalrendite","reduzieren","reduziert","darlehenssumme","häufig","beleihungsauslauf","dadurch","können","sowohl","rate","bankkondition","verbessern"]},{"kind":"article","id":"energiezustand-und-finanzierung","title":"Energiezustand und Finanzierung","category":"Finanzierung","summary":"Energieeffizienz beeinflusst Betriebskosten, Investitionsbedarf, Förderfähigkeit und Bankbewertung.","answer":"Energieeffizienz beeinflusst Betriebskosten, Investitionsbedarf, Förderfähigkeit und Bankbewertung. Der energetische Zustand beeinflusst nicht nur Betriebskosten, sondern zunehmend auch bankseitige Objektbewertung, Modernisierungsbedarf und Förderfähigkeit.","url":"/wissen/energiezustand-und-finanzierung/","keywords":["energiezustand","finanzierung","energieeffizienz","beeinflusst","betriebskosten","investitionsbedarf","förderfähigkeit","bankbewertung","energetische","zustand","nur","sondern","zunehmend","bankseitige","objektbewertung","modernisierungsbedarf"]},{"kind":"article","id":"ertragswertverfahren-kompakt","title":"Ertragswertverfahren kompakt","category":"Immobilienkauf","summary":"Das Ertragswertverfahren leitet den Wert aus nachhaltig erzielbaren Erträgen ab.","answer":"Das Ertragswertverfahren leitet den Wert aus nachhaltig erzielbaren Erträgen ab. Das Ertragswertverfahren leitet den Wert wesentlich aus nachhaltig erzielbaren Erträgen ab. Es trennt Bodenwert und Ertragswert der baulichen Anlagen.","url":"/wissen/ertragswertverfahren-kompakt/","keywords":["ertragswertverfahren","kompakt","leitet","wert","aus","nachhaltig","erzielbaren","erträgen","wesentlich","trennt","bodenwert","ertragswert","baulichen","anlagen"]},{"kind":"article","id":"exit-kosten-berucksichtigen","title":"Exit-Kosten berücksichtigen","category":"Kapitalanlage","summary":"Beim Verkauf entstehen häufig Makler-, Rechts-, Vorfälligkeits- und Abwicklungskosten.","answer":"Beim Verkauf entstehen häufig Makler-, Rechts-, Vorfälligkeits- und Abwicklungskosten. Beim Exit fallen je nach Objekt Makler-, Notar-/Löschungs-, Vorfälligkeits- und gegebenenfalls Steuerkosten an. Ein Verkaufspreis ist daher nicht gleich Nettoerlös.","url":"/wissen/exit-kosten-berucksichtigen/","keywords":["exit-kosten","berücksichtigen","beim","verkauf","entstehen","häufig","makler-","rechts-","vorfälligkeits-","abwicklungskosten","exit","fallen","nach","objekt","notar-","löschungs-","gegebenenfalls","steuerkosten","ein","verkaufspreis","daher","gleich","nettoerlös"]},{"kind":"article","id":"finanzierungsreserve-planen","title":"Finanzierungsreserve planen","category":"Finanzierung","summary":"Eine Reserve schützt vor Kostenüberschreitungen, Leerstand und verzögerten Auszahlungen.","answer":"Eine Reserve schützt vor Kostenüberschreitungen, Leerstand und verzögerten Auszahlungen. Eine Finanzierungsreserve ist liquide verfügbare Sicherheit für Kosten, die nicht oder später von der Bank finanziert werden: Renovierung, Nachträge, Leerstand oder Erwerbsnebenkosten.","url":"/wissen/finanzierungsreserve-planen/","keywords":["finanzierungsreserve","planen","reserve","schützt","vor","kostenüberschreitungen","leerstand","verzögerten","auszahlungen","liquide","verfügbare","sicherheit","kosten","später","bank","finanziert","renovierung","nachträge","erwerbsnebenkosten"]},{"kind":"article","id":"forward-darlehen","title":"Forward-Darlehen","category":"Finanzierung","summary":"Ein Forward-Darlehen sichert Zinsen vor Ablauf der bestehenden Bindung.","answer":"Ein Forward-Darlehen sichert Zinsen vor Ablauf der bestehenden Bindung. Ein Forward-Darlehen sichert heute Konditionen für eine Anschlussfinanzierung, deren Auszahlung erst in der Zukunft beginnt. Es ist damit eine Zinsabsicherung und keine kostenlose Option.","url":"/wissen/forward-darlehen/","keywords":["forward-darlehen","ein","sichert","zinsen","vor","ablauf","bestehenden","bindung","heute","konditionen","anschlussfinanzierung","deren","auszahlung","erst","zukunft","beginnt","damit","zinsabsicherung","keine","kostenlose","option"]},{"kind":"article","id":"gebaudeanteil-berechnen","title":"Gebäudeanteil berechnen","category":"Steuern","summary":"Der Kaufpreis wird für steuerliche Zwecke auf Grund und Boden sowie Gebäude aufgeteilt.","answer":"Der Kaufpreis wird für steuerliche Zwecke auf Grund und Boden sowie Gebäude aufgeteilt. Für steuerliche Abschreibungen muss der Gesamtkaufpreis einschließlich zuordenbarer Nebenkosten auf Grund und Boden sowie Gebäude verteilt werden.","url":"/wissen/gebaudeanteil-berechnen/","keywords":["gebäudeanteil","berechnen","kaufpreis","steuerliche","zwecke","grund","boden","sowie","gebäude","aufgeteilt","abschreibungen","muss","gesamtkaufpreis","einschließlich","zuordenbarer","nebenkosten","verteilt"]},{"kind":"article","id":"immobilien-vergleichen","title":"Immobilien vergleichen","category":"Immobilienkauf","summary":"Zwei Objekte sollten mit denselben Annahmen und demselben Zeitraum verglichen werden.","answer":"Zwei Objekte sollten mit denselben Annahmen und demselben Zeitraum verglichen werden. Ein sinnvoller Vergleich normalisiert Kaufpreis, Nebenkosten, Miete, CapEx, Finanzierung und Haltedauer auf dieselbe Basis.","url":"/wissen/immobilien-vergleichen/","keywords":["immobilien","vergleichen","zwei","objekte","sollten","denselben","annahmen","demselben","zeitraum","verglichen","ein","sinnvoller","vergleich","normalisiert","kaufpreis","nebenkosten","miete","capex","finanzierung","haltedauer","dieselbe","basis"]},{"kind":"article","id":"immobilien-gmbh-oder-privatvermogen","title":"Immobilien-GmbH oder Privatvermögen?","category":"Steuern","summary":"Die Rechtsform verändert Besteuerung, Finanzierung, Haftung und Exit.","answer":"Die Rechtsform verändert Besteuerung, Finanzierung, Haftung und Exit. Privatvermögen und Immobilien-GmbH unterscheiden sich bei laufender Besteuerung, Finanzierung, Entnahmen, Veräußerung und administrativem Aufwand.","url":"/wissen/immobilien-gmbh-oder-privatvermogen/","keywords":["immobilien-gmbh","privatvermögen","rechtsform","verändert","besteuerung","finanzierung","haftung","exit","unterscheiden","laufender","entnahmen","veräußerung","administrativem","aufwand"]},{"kind":"article","id":"indexmiete-kalkulieren","title":"Indexmiete kalkulieren","category":"Vermietung","summary":"Indexmieten koppeln Anpassungen an den Verbraucherpreisindex.","answer":"Indexmieten koppeln Anpassungen an den Verbraucherpreisindex. Bei einer Indexmiete ist die Mietentwicklung an den Verbraucherpreisindex gekoppelt. Die Miete ändert sich nicht automatisch; die Anpassung muss nach den gesetzlichen Anforderungen geltend gemacht werden.","url":"/wissen/indexmiete-kalkulieren/","keywords":["indexmiete","kalkulieren","indexmieten","koppeln","anpassungen","verbraucherpreisindex","mietentwicklung","gekoppelt","miete","ändert","automatisch","anpassung","muss","nach","gesetzlichen","anforderungen","geltend","gemacht"]},{"kind":"article","id":"instandhaltungsrucklage-pro-quadratmeter","title":"Instandhaltungsrücklage pro Quadratmeter","category":"Kapitalanlage","summary":"Ein pauschaler Ansatz kann für die erste Kalkulation helfen.","answer":"Ein pauschaler Ansatz kann für die erste Kalkulation helfen. Pauschale Rücklagen pro Quadratmeter sind nur grobe Planungswerte. Der tatsächliche Bedarf hängt von Alter, Bauart, technischen Gewerken und bereits vorhandenem Rücklagenstand ab.","url":"/wissen/instandhaltungsrucklage-pro-quadratmeter/","keywords":["instandhaltungsrücklage","pro","quadratmeter","ein","pauschaler","ansatz","erste","kalkulation","helfen","pauschale","rücklagen","nur","grobe","planungswerte","tatsächliche","bedarf","hängt","alter","bauart","technischen","gewerken","bereits","vorhandenem","rücklagenstand"]},{"kind":"article","id":"irr-bei-immobilien","title":"IRR bei Immobilien","category":"Kapitalanlage","summary":"Der interne Zinsfuß berücksichtigt Zeitpunkt und Höhe aller Zahlungsströme.","answer":"Der interne Zinsfuß berücksichtigt Zeitpunkt und Höhe aller Zahlungsströme. Die IRR ist der Diskontsatz, bei dem der Kapitalwert einer Zahlungsreihe null wird. Sie berücksichtigt Zeitpunkt und Höhe sämtlicher Ein- und Auszahlungen.","url":"/wissen/irr-bei-immobilien/","keywords":["irr","immobilien","interne","zinsfuß","berücksichtigt","zeitpunkt","höhe","aller","zahlungsströme","diskontsatz","kapitalwert","zahlungsreihe","null","sie","sämtlicher","ein-","auszahlungen"]},{"kind":"article","id":"kapitalwert-verstehen","title":"Kapitalwert verstehen","category":"Kapitalanlage","summary":"Der Kapitalwert diskontiert künftige Zahlungsströme auf heute.","answer":"Der Kapitalwert diskontiert künftige Zahlungsströme auf heute. Der Kapitalwert diskontiert zukünftige Nettozahlungen auf den heutigen Zeitpunkt und zieht die Anfangsinvestition ab.","url":"/wissen/kapitalwert-verstehen/","keywords":["kapitalwert","verstehen","diskontiert","künftige","zahlungsströme","heute","zukünftige","nettozahlungen","heutigen","zeitpunkt","zieht","anfangsinvestition"]},{"kind":"article","id":"kaufnebenkosten-vollstandig-erfassen","title":"Kaufnebenkosten vollständig erfassen","category":"Immobilienkauf","summary":"Grunderwerbsteuer, Notar, Grundbuch und gegebenenfalls Makler erhöhen den Kapitalbedarf.","answer":"Grunderwerbsteuer, Notar, Grundbuch und gegebenenfalls Makler erhöhen den Kapitalbedarf. Zu den Erwerbsnebenkosten gehören insbesondere Grunderwerbsteuer, Notar und Grundbuch sowie gegebenenfalls Maklercourtage. Höhe und Struktur hängen vom Bundesland und konkreten Geschäft ab.","url":"/wissen/kaufnebenkosten-vollstandig-erfassen/","keywords":["kaufnebenkosten","vollständig","erfassen","grunderwerbsteuer","notar","grundbuch","gegebenenfalls","makler","erhöhen","kapitalbedarf","erwerbsnebenkosten","gehören","insbesondere","sowie","maklercourtage","höhe","struktur","hängen","vom","bundesland","konkreten","geschäft"]},{"kind":"article","id":"kaufpreisfaktor-richtig-einordnen","title":"Kaufpreisfaktor richtig einordnen","category":"Kapitalanlage","summary":"Der Faktor ist Kaufpreis geteilt durch Jahresnettokaltmiete.","answer":"Der Faktor ist Kaufpreis geteilt durch Jahresnettokaltmiete. Der Kaufpreisfaktor ist Kaufpreis geteilt durch Jahresnettokaltmiete und damit der Kehrwert der Bruttomietrendite, sofern dieselben Bezugsgrößen verwendet werden.","url":"/wissen/kaufpreisfaktor-richtig-einordnen/","keywords":["kaufpreisfaktor","richtig","einordnen","faktor","kaufpreis","geteilt","durch","jahresnettokaltmiete","damit","kehrwert","bruttomietrendite","sofern","dieselben","bezugsgrößen","verwendet"]},{"kind":"article","id":"leerstand-richtig-bewerten","title":"Leerstand richtig bewerten","category":"Vermietung","summary":"Leerstand kann marktbedingt, technisch oder strategisch sein.","answer":"Leerstand kann marktbedingt, technisch oder strategisch sein. Leerstand kann temporär, strukturell oder strategisch sein. Die wirtschaftliche Bewertung hängt davon ab, ob die Einheit kurzfristig vermietbar ist oder ein technisches/rechtliches Problem vorliegt.","url":"/wissen/leerstand-richtig-bewerten/","keywords":["leerstand","richtig","bewerten","marktbedingt","technisch","strategisch","sein","temporär","strukturell","wirtschaftliche","bewertung","hängt","davon","einheit","kurzfristig","vermietbar","ein","technisches","rechtliches","problem","vorliegt"]},{"kind":"article","id":"ltv-verstehen","title":"LTV verstehen","category":"Finanzierung","summary":"Loan-to-Value setzt Darlehen zum Immobilienwert oder Beleihungswert ins Verhältnis.","answer":"Loan-to-Value setzt Darlehen zum Immobilienwert oder Beleihungswert ins Verhältnis. Loan-to-Value beschreibt das Verhältnis von Darlehen zu einem definierten Objektwert. Im deutschen Bankkontext ist davon der Beleihungsauslauf auf Basis des Beleihungswerts zu unterscheiden.","url":"/wissen/ltv-verstehen/","keywords":["ltv","verstehen","loan-to-value","setzt","darlehen","zum","immobilienwert","beleihungswert","ins","verhältnis","beschreibt","einem","definierten","objektwert","deutschen","bankkontext","davon","beleihungsauslauf","basis","beleihungswerts","unterscheiden"]},{"kind":"article","id":"mietausfall-kalkulieren","title":"Mietausfall kalkulieren","category":"Kapitalanlage","summary":"Mietausfall umfasst Leerstand, Zahlungsstörungen und nicht nahtlose Neuvermietung.","answer":"Mietausfall umfasst Leerstand, Zahlungsstörungen und nicht nahtlose Neuvermietung. Mietausfall umfasst nicht nur dauerhaft unbezahlte Miete, sondern auch Leerstand zwischen Mietverhältnissen, Verzögerungen und uneinbringliche Forderungen.","url":"/wissen/mietausfall-kalkulieren/","keywords":["mietausfall","kalkulieren","umfasst","leerstand","zahlungsstörungen","nahtlose","neuvermietung","nur","dauerhaft","unbezahlte","miete","sondern","zwischen","mietverhältnissen","verzögerungen","uneinbringliche","forderungen"]},{"kind":"article","id":"mietmultiplikator-und-faktor","title":"Mietmultiplikator und Faktor","category":"Kapitalanlage","summary":"Der Faktor beschreibt, wie viele Jahresnettokaltmieten dem Kaufpreis entsprechen.","answer":"Der Faktor beschreibt, wie viele Jahresnettokaltmieten dem Kaufpreis entsprechen. Mietmultiplikator, Vervielfältiger und Kaufpreisfaktor werden im Markt häufig synonym verwendet: Kaufpreis geteilt durch Jahresnettokaltmiete.","url":"/wissen/mietmultiplikator-und-faktor/","keywords":["mietmultiplikator","faktor","beschreibt","wie","viele","jahresnettokaltmieten","kaufpreis","entsprechen","vervielfältiger","kaufpreisfaktor","markt","häufig","synonym","verwendet","geteilt","durch","jahresnettokaltmiete"]},{"kind":"article","id":"mietspiegel-richtig-nutzen","title":"Mietspiegel richtig nutzen","category":"Vermietung","summary":"Der Mietspiegel unterstützt die Einordnung ortsüblicher Vergleichsmieten.","answer":"Der Mietspiegel unterstützt die Einordnung ortsüblicher Vergleichsmieten. Mietspiegel bilden die ortsübliche Vergleichsmiete nach gesetzlichen Kriterien ab und sind kein allgemeiner Marktpreisrechner für jede Wohnung.","url":"/wissen/mietspiegel-richtig-nutzen/","keywords":["mietspiegel","richtig","nutzen","unterstützt","einordnung","ortsüblicher","vergleichsmieten","bilden","ortsübliche","vergleichsmiete","nach","gesetzlichen","kriterien","kein","allgemeiner","marktpreisrechner","jede","wohnung"]},{"kind":"article","id":"mietsteigerungen-realistisch-modellieren","title":"Mietsteigerungen realistisch modellieren","category":"Vermietung","summary":"Mietsteigerungen sind rechtlich und marktseitig begrenzt.","answer":"Mietsteigerungen sind rechtlich und marktseitig begrenzt. Mietsteigerungen hängen vom Vertragstyp, Mietrecht, Ausgangsniveau und Mieterwechsel ab. Eine pauschale jährliche Wachstumsrate kann rechtlich nicht durchsetzbare Erträge simulieren.","url":"/wissen/mietsteigerungen-realistisch-modellieren/","keywords":["mietsteigerungen","realistisch","modellieren","rechtlich","marktseitig","begrenzt","hängen","vom","vertragstyp","mietrecht","ausgangsniveau","mieterwechsel","pauschale","jährliche","wachstumsrate","durchsetzbare","erträge","simulieren"]},{"kind":"article","id":"mietvertrag-und-ertragssicherheit","title":"Mietvertrag und Ertragssicherheit","category":"Vermietung","summary":"Die vertragliche Miete ist nur dann belastbar, wenn Vertrag und Zahlungshistorie geprüft sind.","answer":"Die vertragliche Miete ist nur dann belastbar, wenn Vertrag und Zahlungshistorie geprüft sind. Der Mietvertrag bestimmt Höhe, Anpassungsmechanismus, Laufzeit, Nebenkostenregelung und weitere Rechte. Diese Punkte beeinflussen die Nachhaltigkeit des Ertrags.","url":"/wissen/mietvertrag-und-ertragssicherheit/","keywords":["mietvertrag","ertragssicherheit","vertragliche","miete","nur","dann","belastbar","wenn","vertrag","zahlungshistorie","geprüft","bestimmt","höhe","anpassungsmechanismus","laufzeit","nebenkostenregelung","weitere","rechte","diese","punkte","beeinflussen","nachhaltigkeit","ertrags"]},{"kind":"article","id":"mikrolage-vor-stadtname","title":"Mikrolage vor Stadtname","category":"Marktanalysen","summary":"Straße, Block und fußläufige Umgebung sind oft wichtiger als die Stadt als Ganzes.","answer":"Straße, Block und fußläufige Umgebung sind oft wichtiger als die Stadt als Ganzes. Innerhalb derselben Stadt können Kaufpreis, Miete, Leerstandsrisiko und Zielgruppe straßenweise deutlich variieren.","url":"/wissen/mikrolage-vor-stadtname/","keywords":["mikrolage","vor","stadtname","straße","block","fußläufige","umgebung","oft","wichtiger","stadt","ganzes","innerhalb","derselben","können","kaufpreis","miete","leerstandsrisiko","zielgruppe","straßenweise","deutlich","variieren"]},{"kind":"article","id":"modernisierungsumlage","title":"Modernisierungsumlage","category":"Vermietung","summary":"Bestimmte Modernisierungskosten können unter gesetzlichen Voraussetzungen teilweise umgelegt werden.","answer":"Bestimmte Modernisierungskosten können unter gesetzlichen Voraussetzungen teilweise umgelegt werden. Nach § 559 BGB können unter Voraussetzungen 8 % bestimmter Modernisierungskosten auf die Jahresmiete umgelegt werden. Erhaltungsanteile sind herauszurechnen.","url":"/wissen/modernisierungsumlage/","keywords":["modernisierungsumlage","bestimmte","modernisierungskosten","können","unter","gesetzlichen","voraussetzungen","teilweise","umgelegt","nach","559","bgb","bestimmter","jahresmiete","erhaltungsanteile","herauszurechnen"]},{"kind":"article","id":"nicht-umlagefahiges-hausgeld","title":"Nicht umlagefähiges Hausgeld","category":"Vermietung","summary":"Nicht umlagefähige Bestandteile des Hausgelds trägt der Eigentümer selbst.","answer":"Nicht umlagefähige Bestandteile des Hausgelds trägt der Eigentümer selbst. Hausgeld umfasst umlagefähige Betriebskosten, nicht umlagefähige Verwaltung-/sonstige Kosten und Zuführungen zur Erhaltungsrücklage. Für die Eigentümerrechnung dürfen diese Bestandteile nicht vermischt werden.","url":"/wissen/nicht-umlagefahiges-hausgeld/","keywords":["umlagefähiges","hausgeld","umlagefähige","bestandteile","hausgelds","trägt","eigentümer","selbst","umfasst","betriebskosten","verwaltung-","sonstige","kosten","zuführungen","zur","erhaltungsrücklage","eigentümerrechnung","dürfen","diese","vermischt"]},{"kind":"article","id":"portfolio-risiko-messen","title":"Portfolio-Risiko messen","category":"Kapitalanlage","summary":"Mehrere Objekte reduzieren nicht automatisch Risiko.","answer":"Mehrere Objekte reduzieren nicht automatisch Risiko. Portfolio-Risiko entsteht aus Konzentrationen nach Standort, Objektart, Mieter, Finanzierung, Zinsbindung und technischem Zustand.","url":"/wissen/portfolio-risiko-messen/","keywords":["portfolio-risiko","messen","mehrere","objekte","reduzieren","automatisch","risiko","entsteht","aus","konzentrationen","nach","standort","objektart","mieter","finanzierung","zinsbindung","technischem","zustand"]},{"kind":"article","id":"qng-und-effizienzhaus-40","title":"QNG und Effizienzhaus 40","category":"Finanzierung","summary":"QNG verbindet Nachhaltigkeitsanforderungen mit förderfähigen Gebäudestandards.","answer":"QNG verbindet Nachhaltigkeitsanforderungen mit förderfähigen Gebäudestandards. QNG ist ein Nachhaltigkeitsnachweis und nicht identisch mit dem energetischen Effizienzhausstandard. Bei bestimmten Förder-/Steuertatbeständen müssen beide Anforderungen gemeinsam erfüllt sein.","url":"/wissen/qng-und-effizienzhaus-40/","keywords":["qng","effizienzhaus","verbindet","nachhaltigkeitsanforderungen","förderfähigen","gebäudestandards","ein","nachhaltigkeitsnachweis","identisch","energetischen","effizienzhausstandard","bestimmten","förder-","steuertatbeständen","müssen","beide","anforderungen","gemeinsam","erfüllt","sein"]},{"kind":"article","id":"restnutzungsgutachten-erklart","title":"Restnutzungsgutachten erklärt","category":"Steuern","summary":"Ein Restnutzungsgutachten kann unter Voraussetzungen eine kürzere tatsächliche Nutzungsdauer begründen.","answer":"Ein Restnutzungsgutachten kann unter Voraussetzungen eine kürzere tatsächliche Nutzungsdauer begründen. Eine tatsächlich kürzere Nutzungsdauer kann nach § 7 Abs. 4 Satz 2 EStG zu einer höheren jährlichen AfA führen, wenn sie belastbar nachgewiesen wird.","url":"/wissen/restnutzungsgutachten-erklart/","keywords":["restnutzungsgutachten","erklärt","ein","unter","voraussetzungen","kürzere","tatsächliche","nutzungsdauer","begründen","tatsächlich","nach","abs","satz","estg","höheren","jährlichen","afa","führen","wenn","sie","belastbar","nachgewiesen"]},{"kind":"article","id":"sachwertverfahren-kompakt","title":"Sachwertverfahren kompakt","category":"Immobilienkauf","summary":"Das Sachwertverfahren betrachtet Herstellungskosten, Alterswertminderung und Marktanpassung.","answer":"Das Sachwertverfahren betrachtet Herstellungskosten, Alterswertminderung und Marktanpassung. Das Sachwertverfahren leitet den Wert aus Bodenwert und Herstellungskosten der baulichen Anlagen unter Berücksichtigung von Alter und Marktanpassung ab.","url":"/wissen/sachwertverfahren-kompakt/","keywords":["sachwertverfahren","kompakt","betrachtet","herstellungskosten","alterswertminderung","marktanpassung","leitet","wert","aus","bodenwert","baulichen","anlagen","unter","berücksichtigung","alter"]},{"kind":"article","id":"sensitivitatsanalyse-nutzen","title":"Sensitivitätsanalyse nutzen","category":"Kapitalanlage","summary":"Eine Sensitivitätsanalyse zeigt, welche Annahmen das Ergebnis am stärksten verändern.","answer":"Eine Sensitivitätsanalyse zeigt, welche Annahmen das Ergebnis am stärksten verändern. Eine Sensitivitätsanalyse verändert jeweils einzelne Annahmen und zeigt, welche Variablen das Ergebnis besonders treiben.","url":"/wissen/sensitivitatsanalyse-nutzen/","keywords":["sensitivitätsanalyse","nutzen","zeigt","welche","annahmen","ergebnis","stärksten","verändern","verändert","jeweils","einzelne","variablen","besonders","treiben"]},{"kind":"article","id":"sonderumlage-als-risiko","title":"Sonderumlage als Risiko","category":"Immobilienkauf","summary":"Sonderumlagen können kurzfristig erhebliches Eigenkapital binden.","answer":"Sonderumlagen können kurzfristig erhebliches Eigenkapital binden. Eine Sonderumlage ist ein zusätzlicher Finanzierungsbeitrag der Wohnungseigentümer, wenn laufende Mittel und Rücklage für Maßnahmen oder Verpflichtungen nicht ausreichen.","url":"/wissen/sonderumlage-als-risiko/","keywords":["sonderumlage","risiko","sonderumlagen","können","kurzfristig","erhebliches","eigenkapital","binden","ein","zusätzlicher","finanzierungsbeitrag","wohnungseigentümer","wenn","laufende","mittel","rücklage","maßnahmen","verpflichtungen","ausreichen"]},{"kind":"article","id":"spekulationsfrist-im-uberblick","title":"Spekulationsfrist im Überblick","category":"Steuern","summary":"Private Veräußerungsgewinne können innerhalb gesetzlicher Fristen steuerpflichtig sein.","answer":"Private Veräußerungsgewinne können innerhalb gesetzlicher Fristen steuerpflichtig sein. Bei privaten Grundstücksveräußerungen kann § 23 EStG innerhalb der Zehnjahresfrist zu steuerpflichtigen privaten Veräußerungsgeschäften führen. Für bestimmte Eigennutzungsfälle existieren Ausnahmen.","url":"/wissen/spekulationsfrist-im-uberblick/","keywords":["spekulationsfrist","überblick","private","veräußerungsgewinne","können","innerhalb","gesetzlicher","fristen","steuerpflichtig","sein","privaten","grundstücksveräußerungen","estg","zehnjahresfrist","steuerpflichtigen","veräußerungsgeschäften","führen","bestimmte","eigennutzungsfälle","existieren","ausnahmen"]},{"kind":"article","id":"staffelmiete-kalkulieren","title":"Staffelmiete kalkulieren","category":"Vermietung","summary":"Staffelmieten machen künftige nominale Mieten planbarer.","answer":"Staffelmieten machen künftige nominale Mieten planbarer. Bei der Staffelmiete werden zukünftige Miethöhen beziehungsweise Erhöhungen in Euro vertraglich festgelegt. Zwischen den Staffeln muss die Miete mindestens ein Jahr unverändert bleiben.","url":"/wissen/staffelmiete-kalkulieren/","keywords":["staffelmiete","kalkulieren","staffelmieten","machen","künftige","nominale","mieten","planbarer","zukünftige","miethöhen","beziehungsweise","erhöhungen","euro","vertraglich","festgelegt","zwischen","staffeln","muss","miete","mindestens","ein","jahr","unverändert","bleiben"]},{"kind":"article","id":"steuerlicher-gewinn-und-echter-cashflow","title":"Steuerlicher Gewinn und echter Cashflow","category":"Steuern","summary":"Steuerlicher Gewinn und Liquiditätsüberschuss sind unterschiedliche Größen.","answer":"Steuerlicher Gewinn und Liquiditätsüberschuss sind unterschiedliche Größen. Steuerlicher Gewinn und Cashflow messen unterschiedliche Dinge. AfA mindert den steuerlichen Gewinn ohne laufenden Zahlungsabfluss; Tilgung mindert Liquidität, ist aber grundsätzlich keine Werbungskostenposition.","url":"/wissen/steuerlicher-gewinn-und-echter-cashflow/","keywords":["steuerlicher","gewinn","echter","cashflow","liquiditätsüberschuss","unterschiedliche","größen","messen","dinge","afa","mindert","steuerlichen","ohne","laufenden","zahlungsabfluss","tilgung","liquidität","aber","grundsätzlich","keine","werbungskostenposition"]},{"kind":"article","id":"tilgung-oder-sondertilgung","title":"Tilgung oder Sondertilgung?","category":"Finanzierung","summary":"Höhere Tilgung reduziert die Restschuld schneller, bindet aber monatliche Liquidität.","answer":"Höhere Tilgung reduziert die Restschuld schneller, bindet aber monatliche Liquidität. Höhere laufende Tilgung erhöht die verpflichtende Rate und reduziert planmäßig die Restschuld. Sondertilgung bietet Flexibilität, wenn sie vertraglich vereinbart ist und Liquidität tatsächlich vorhanden ist.","url":"/wissen/tilgung-oder-sondertilgung/","keywords":["tilgung","sondertilgung","höhere","reduziert","restschuld","schneller","bindet","aber","monatliche","liquidität","laufende","erhöht","verpflichtende","rate","planmäßig","bietet","flexibilität","wenn","sie","vertraglich","vereinbart","tatsächlich","vorhanden"]},{"kind":"article","id":"umlagefahige-betriebskosten","title":"Umlagefähige Betriebskosten","category":"Vermietung","summary":"Umlagefähige Kosten können bei wirksamer Vereinbarung auf Mieter verteilt werden.","answer":"Umlagefähige Kosten können bei wirksamer Vereinbarung auf Mieter verteilt werden. Umlagefähige Betriebskosten richten sich nach Betriebskostenverordnung und Mietvertrag. Nicht jede Eigentümerkostenposition ist automatisch auf den Mieter übertragbar.","url":"/wissen/umlagefahige-betriebskosten/","keywords":["umlagefähige","betriebskosten","kosten","können","wirksamer","vereinbarung","mieter","verteilt","richten","nach","betriebskostenverordnung","mietvertrag","jede","eigentümerkostenposition","automatisch","übertragbar"]},{"kind":"article","id":"vergleichswertverfahren-kompakt","title":"Vergleichswertverfahren kompakt","category":"Immobilienkauf","summary":"Vergleichspreise ähnlicher Objekte bilden die Grundlage.","answer":"Vergleichspreise ähnlicher Objekte bilden die Grundlage. Das Vergleichswertverfahren leitet den Wert aus Kaufpreisen hinreichend vergleichbarer Grundstücke beziehungsweise Wohnungen ab.","url":"/wissen/vergleichswertverfahren-kompakt/","keywords":["vergleichswertverfahren","kompakt","vergleichspreise","ähnlicher","objekte","bilden","grundlage","leitet","wert","aus","kaufpreisen","hinreichend","vergleichbarer","grundstücke","beziehungsweise","wohnungen"]},{"kind":"article","id":"vom-rechner-zum-bankgesprach","title":"Vom Rechner zum Bankgespräch","category":"Finanzierung","summary":"Eine nachvollziehbare Kalkulation verbessert die Vorbereitung.","answer":"Eine nachvollziehbare Kalkulation verbessert die Vorbereitung. Ein Online-Rechner liefert eine mathematische Rate, aber keine Kreditentscheidung. Banken prüfen zusätzlich Einkommen, Verpflichtungen, Bonität, Objektunterlagen und eigenen Beleihungswert.","url":"/wissen/vom-rechner-zum-bankgesprach/","keywords":["vom","rechner","zum","bankgespräch","nachvollziehbare","kalkulation","verbessert","vorbereitung","ein","online-rechner","liefert","mathematische","rate","aber","keine","kreditentscheidung","banken","prüfen","zusätzlich","einkommen","verpflichtungen","bonität","objektunterlagen","eigenen","beleihungswert"]},{"kind":"article","id":"wann-lohnt-sich-ein-mehrfamilienhaus","title":"Wann lohnt sich ein Mehrfamilienhaus?","category":"Immobilienkauf","summary":"Ein Mehrfamilienhaus muss als Gesamtbetrieb aus Mieten, Kosten, Investitionen und Finanzierung betrachtet werden.","answer":"Ein Mehrfamilienhaus muss als Gesamtbetrieb aus Mieten, Kosten, Investitionen und Finanzierung betrachtet werden. Ein Mehrfamilienhaus ist wirtschaftlich attraktiv, wenn Ertrag, CapEx, Finanzierung und Bewirtschaftung auf Portfolioebene tragfähig sind – nicht allein wegen eines niedrigen Kaufpreisfaktors.","url":"/wissen/wann-lohnt-sich-ein-mehrfamilienhaus/","keywords":["wann","lohnt","ein","mehrfamilienhaus","muss","gesamtbetrieb","aus","mieten","kosten","investitionen","finanzierung","betrachtet","wirtschaftlich","attraktiv","wenn","ertrag","capex","bewirtschaftung","portfolioebene","tragfähig","allein","wegen","niedrigen","kaufpreisfaktors"]},{"kind":"article","id":"weg-rucklage-verstehen","title":"WEG-Rücklage verstehen","category":"Vermietung","summary":"Die Erhaltungsrücklage dient künftigen Maßnahmen am Gemeinschaftseigentum.","answer":"Die Erhaltungsrücklage dient künftigen Maßnahmen am Gemeinschaftseigentum. Die Erhaltungsrücklage gehört der Gemeinschaft und dient zukünftigen Maßnahmen am Gemeinschaftseigentum. Der auf eine Wohnung entfallende rechnerische Anteil ist nicht frei verfügbares Guthaben des einzelnen Eigentümers.","url":"/wissen/weg-rucklage-verstehen/","keywords":["weg-rücklage","verstehen","erhaltungsrücklage","dient","künftigen","maßnahmen","gemeinschaftseigentum","gehört","gemeinschaft","zukünftigen","wohnung","entfallende","rechnerische","anteil","frei","verfügbares","guthaben","einzelnen","eigentümers"]},{"kind":"article","id":"wertsteigerung-als-szenario","title":"Wertsteigerung als Szenario","category":"Kapitalanlage","summary":"Wertzuwachs ist unsicher und sollte nicht zur Rettung eines schwachen laufenden Cashflows dienen.","answer":"Wertzuwachs ist unsicher und sollte nicht zur Rettung eines schwachen laufenden Cashflows dienen. Wertsteigerung ist kein laufender Zahlungsstrom und keine garantierte Rendite. Sie hängt von Markt, Mikrolage, Objektqualität, Zinsen und Angebots-/Nachfragedynamik ab.","url":"/wissen/wertsteigerung-als-szenario/","keywords":["wertsteigerung","szenario","wertzuwachs","unsicher","sollte","zur","rettung","schwachen","laufenden","cashflows","dienen","kein","laufender","zahlungsstrom","keine","garantierte","rendite","sie","hängt","markt","mikrolage","objektqualität","zinsen","angebots-","nachfragedynamik"]},{"kind":"article","id":"wie-berechnet-man-die-eigenkapitalrendite","title":"Wie berechnet man die Eigenkapitalrendite?","category":"Kapitalanlage","summary":"Die Eigenkapitalrendite setzt den jährlichen Vermögenseffekt ins Verhältnis zum tatsächlich eingesetzten Eigenkapital.","answer":"Die Eigenkapitalrendite setzt den jährlichen Vermögenseffekt ins Verhältnis zum tatsächlich eingesetzten Eigenkapital. Eigenkapitalrendite ist nur sinnvoll, wenn klar definiert wird, welcher Ertrag im Zähler steht: laufender Cashflow, Cashflow plus Tilgung oder Total Return inklusive Wertänderung.","url":"/wissen/wie-berechnet-man-die-eigenkapitalrendite/","keywords":["wie","berechnet","man","eigenkapitalrendite","setzt","jährlichen","vermögenseffekt","ins","verhältnis","zum","tatsächlich","eingesetzten","eigenkapital","nur","sinnvoll","wenn","klar","definiert","welcher","ertrag","zähler","steht","laufender","cashflow","plus","tilgung","total","return","inklusive","wertänderung"]},{"kind":"article","id":"wohnflachenberechnung-prufen","title":"Wohnflächenberechnung prüfen","category":"Immobilienkauf","summary":"Balkone, Dachschrägen und Nebenflächen werden je nach Regelwerk unterschiedlich berücksichtigt.","answer":"Balkone, Dachschrägen und Nebenflächen werden je nach Regelwerk unterschiedlich berücksichtigt. Wohnfläche beeinflusst Kaufpreis pro m², Miete, Betriebskostenverteilung und teilweise Finanzierung. Fehler können daher mehrfach wirtschaftlich wirken.","url":"/wissen/wohnflachenberechnung-prufen/","keywords":["wohnflächenberechnung","prüfen","balkone","dachschrägen","nebenflächen","nach","regelwerk","unterschiedlich","berücksichtigt","wohnfläche","beeinflusst","kaufpreis","pro","miete","betriebskostenverteilung","teilweise","finanzierung","fehler","können","daher","mehrfach","wirtschaftlich","wirken"]},{"kind":"article","id":"zinsbindung-strategisch-wahlen","title":"Zinsbindung strategisch wählen","category":"Finanzierung","summary":"Die Zinsbindung verteilt Zinsänderungsrisiko und Flexibilität.","answer":"Die Zinsbindung verteilt Zinsänderungsrisiko und Flexibilität. Eine längere Zinsbindung kauft Planungssicherheit und kann einen Zinsaufschlag enthalten; eine kürzere Bindung kann günstiger starten, erhöht aber das frühere Anschlussrisiko.","url":"/wissen/zinsbindung-strategisch-wahlen/","keywords":["zinsbindung","strategisch","wählen","verteilt","zinsänderungsrisiko","flexibilität","längere","kauft","planungssicherheit","einen","zinsaufschlag","enthalten","kürzere","bindung","günstiger","starten","erhöht","aber","frühere","anschlussrisiko"]},{"kind":"article","id":"zinsanderungsstress-testen","title":"Zinsänderungsstress testen","category":"Finanzierung","summary":"Ein guter Plan rechnet nicht nur mit dem heutigen Sollzins.","answer":"Ein guter Plan rechnet nicht nur mit dem heutigen Sollzins. Der Zinsstress zeigt, ob die Finanzierung nach Ende der Zinsbindung auch bei höheren Anschlusszinsen tragfähig bleibt.","url":"/wissen/zinsanderungsstress-testen/","keywords":["zinsänderungsstress","testen","ein","guter","plan","rechnet","nur","heutigen","sollzins","zinsstress","zeigt","finanzierung","nach","ende","zinsbindung","höheren","anschlusszinsen","tragfähig","bleibt"]},{"kind":"article","id":"7b-estg-im-uberblick","title":"§ 7b EStG im Überblick","category":"Steuern","summary":"Die Sonderabschreibung für Mietwohnungsneubau ist an Voraussetzungen und Grenzen gebunden.","answer":"Die Sonderabschreibung für Mietwohnungsneubau ist an Voraussetzungen und Grenzen gebunden. § 7b EStG ermöglicht Sonderabschreibungen zusätzlich zur regulären Gebäude-AfA. Für aktuelle Fälle sind unter anderem Bauantrags-/Bauanzeigezeitraum, neue Wohnung, entgeltliche Wohnnutzung und die gesetzlichen Kostenobergrenzen relevant.","url":"/wissen/7b-estg-im-uberblick/","keywords":["estg","überblick","sonderabschreibung","mietwohnungsneubau","voraussetzungen","grenzen","gebunden","ermöglicht","sonderabschreibungen","zusätzlich","zur","regulären","gebäude-afa","aktuelle","fälle","unter","anderem","bauantrags-","bauanzeigezeitraum","neue","wohnung","entgeltliche","wohnnutzung","gesetzlichen","kostenobergrenzen","relevant"]},{"kind":"lexicon","id":"abgeschlossenheitsbescheinigung","title":"Abgeschlossenheitsbescheinigung","category":"Immobilienkauf","summary":"Bestätigung, dass Einheiten baulich abgeschlossen sind.","answer":"Bestätigung, dass Einheiten baulich abgeschlossen sind. Die Abgeschlossenheitsbescheinigung bestätigt gegenüber dem Grundbuchamt, dass Einheiten baulich hinreichend abgeschlossen sind und ist regelmäßig Voraussetzung für die Begründung von Wohnungs-/Teileigentum.","url":"/lexikon/abgeschlossenheitsbescheinigung/","keywords":["abgeschlossenheitsbescheinigung","bestätigung","dass","einheiten","baulich","abgeschlossen","bestätigt","gegenüber","grundbuchamt","hinreichend","regelmäßig","voraussetzung","begründung","wohnungs-","teileigentum"]},{"kind":"lexicon","id":"afa","title":"AfA","category":"Steuern","summary":"Absetzung für Abnutzung: steuerliche Verteilung des abschreibungsfähigen Gebäudewerts über die Nutzungsdauer.","answer":"Absetzung für Abnutzung: steuerliche Verteilung des abschreibungsfähigen Gebäudewerts über die Nutzungsdauer. AfA verteilt die steuerlich abschreibungsfähigen Anschaffungs- oder Herstellungskosten eines Gebäudes über die Nutzungsdauer. Grund und Boden ist nicht abschreibbar. Bei Erwerb müssen Kaufpreis und zuordenbare Nebenkosten daher auf Gebäude und Boden aufgeteilt werden.","url":"/lexikon/afa/","keywords":["afa","absetzung","abnutzung","steuerliche","verteilung","abschreibungsfähigen","gebäudewerts","über","nutzungsdauer","verteilt","steuerlich","anschaffungs-","herstellungskosten","gebäudes","grund","boden","abschreibbar","erwerb","müssen","kaufpreis","zuordenbare","nebenkosten","daher","gebäude","aufgeteilt"]},{"kind":"lexicon","id":"angebotsmiete","title":"Angebotsmiete","category":"Vermietung","summary":"In Inseraten verlangte Miete; nicht identisch mit tatsächlich vereinbarter Bestandsmiete.","answer":"In Inseraten verlangte Miete; nicht identisch mit tatsächlich vereinbarter Bestandsmiete. Angebotsmiete ist die in Inseraten verlangte Miete und nicht automatisch die tatsächlich vereinbarte Vertragsmiete oder rechtlich zulässige Miete. Sie ist ein Marktindikator mit Selektionsverzerrungen.","url":"/lexikon/angebotsmiete/","keywords":["angebotsmiete","inseraten","verlangte","miete","identisch","tatsächlich","vereinbarter","bestandsmiete","automatisch","vereinbarte","vertragsmiete","rechtlich","zulässige","sie","ein","marktindikator","selektionsverzerrungen"]},{"kind":"lexicon","id":"ankaufsprufung","title":"Ankaufsprüfung","category":"Immobilienkauf","summary":"Strukturierte wirtschaftliche, rechtliche, technische und steuerliche Prüfung vor Kauf.","answer":"Strukturierte wirtschaftliche, rechtliche, technische und steuerliche Prüfung vor Kauf. Ankaufsprüfung ist die strukturierte Prüfung eines Immobilienkaufs vor Bindung. Sie verbindet Unterlagen, technische Risiken, Erträge, Kaufpreis, Finanzierung und rechtliche Besonderheiten zu einer belastbaren Entscheidung.","url":"/lexikon/ankaufsprufung/","keywords":["ankaufsprüfung","strukturierte","wirtschaftliche","rechtliche","technische","steuerliche","prüfung","vor","kauf","immobilienkaufs","bindung","sie","verbindet","unterlagen","risiken","erträge","kaufpreis","finanzierung","besonderheiten","belastbaren","entscheidung"]},{"kind":"lexicon","id":"annuitat","title":"Annuität","category":"Finanzierung","summary":"Regelmäßig gleichbleibende Rate aus Zins und Tilgung.","answer":"Regelmäßig gleichbleibende Rate aus Zins und Tilgung. Die Annuität ist die regelmäßig gleichbleibende Rate eines klassischen Annuitätendarlehens während der Sollzinsbindung. Sie besteht aus Zins und Tilgung; mit sinkender Restschuld sinkt der Zinsanteil und der Tilgungsanteil steigt.","url":"/lexikon/annuitat/","keywords":["annuität","regelmäßig","gleichbleibende","rate","aus","zins","tilgung","klassischen","annuitätendarlehens","während","sollzinsbindung","sie","besteht","sinkender","restschuld","sinkt","zinsanteil","tilgungsanteil","steigt"]},{"kind":"lexicon","id":"anschlussfinanzierung","title":"Anschlussfinanzierung","category":"Finanzierung","summary":"Finanzierung der Restschuld nach Ablauf der Zinsbindung.","answer":"Finanzierung der Restschuld nach Ablauf der Zinsbindung. Anschlussfinanzierung ist die Finanzierung der verbleibenden Restschuld nach Ende einer Zinsbindung. Sie kann als Prolongation bei derselben Bank, Umschuldung oder vorab als Forward-Darlehen gestaltet werden.","url":"/lexikon/anschlussfinanzierung/","keywords":["anschlussfinanzierung","finanzierung","restschuld","nach","ablauf","zinsbindung","verbleibenden","ende","sie","prolongation","derselben","bank","umschuldung","vorab","forward-darlehen","gestaltet"]},{"kind":"lexicon","id":"ausfallwagnis","title":"Ausfallwagnis","category":"Immobilienkauf","summary":"Kalkulatorischer Abschlag für Leerstand und Zahlungsausfälle.","answer":"Kalkulatorischer Abschlag für Leerstand und Zahlungsausfälle. Ausfallwagnis ist die erwartete Belastung aus nicht eingehenden Forderungen oder Erträgen. In Bewertungs- und Investmentmodellen wird es als Risikoabschlag beziehungsweise Kostenkomponente berücksichtigt.","url":"/lexikon/ausfallwagnis/","keywords":["ausfallwagnis","kalkulatorischer","abschlag","leerstand","zahlungsausfälle","erwartete","belastung","aus","eingehenden","forderungen","erträgen","bewertungs-","investmentmodellen","risikoabschlag","beziehungsweise","kostenkomponente","berücksichtigt"]},{"kind":"lexicon","id":"baulast","title":"Baulast","category":"Immobilienkauf","summary":"Öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers.","answer":"Öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers. Eine Baulast ist eine öffentlich-rechtliche Verpflichtung eines Grundstückseigentümers gegenüber der Bauaufsichtsbehörde. Sie steht je nach Bundesland im Baulastenverzeichnis und kann Nutzung, Bebaubarkeit oder Wert beeinflussen.","url":"/lexikon/baulast/","keywords":["baulast","öffentlich-rechtliche","verpflichtung","grundstückseigentümers","gegenüber","bauaufsichtsbehörde","sie","steht","nach","bundesland","baulastenverzeichnis","nutzung","bebaubarkeit","wert","beeinflussen"]},{"kind":"lexicon","id":"baunebenkosten","title":"Baunebenkosten","category":"Immobilienkauf","summary":"Planungs-, Genehmigungs- und sonstige Kosten zusätzlich zu Bauleistungen.","answer":"Planungs-, Genehmigungs- und sonstige Kosten zusätzlich zu Bauleistungen. Baunebenkosten sind Kosten rund um Planung, Genehmigung, Finanzierung und Bauabwicklung, die zusätzlich zu den reinen Bauwerkskosten entstehen. Sie werden bei Neubau- und Sanierungsbudgets separat kalkuliert und können einen erheblichen Anteil der Gesamtinvestition ausmachen.","url":"/lexikon/baunebenkosten/","keywords":["baunebenkosten","planungs-","genehmigungs-","sonstige","kosten","zusätzlich","bauleistungen","rund","planung","genehmigung","finanzierung","bauabwicklung","reinen","bauwerkskosten","entstehen","sie","neubau-","sanierungsbudgets","separat","kalkuliert","können","einen","erheblichen","anteil","gesamtinvestition","ausmachen"]},{"kind":"lexicon","id":"beleihungsauslauf","title":"Beleihungsauslauf","category":"Finanzierung","summary":"Verhältnis von Darlehen zu bankseitigem Beleihungswert.","answer":"Verhältnis von Darlehen zu bankseitigem Beleihungswert. Der Beleihungsauslauf ist das Verhältnis der relevanten Darlehenssumme zum bankinternen Beleihungswert. Er unterscheidet sich von der einfachen Kaufpreisfinanzierungsquote, weil der Beleihungswert unter dem Kaufpreis liegen kann. Banken nutzen Beleihungsausläufe häufig zur Risikoklassifizierung und Konditionsstaffelung.","url":"/lexikon/beleihungsauslauf/","keywords":["beleihungsauslauf","verhältnis","darlehen","bankseitigem","beleihungswert","relevanten","darlehenssumme","zum","bankinternen","unterscheidet","einfachen","kaufpreisfinanzierungsquote","weil","unter","kaufpreis","liegen","banken","nutzen","beleihungsausläufe","häufig","zur","risikoklassifizierung","konditionsstaffelung"]},{"kind":"lexicon","id":"beleihungswert","title":"Beleihungswert","category":"Finanzierung","summary":"Vorsichtig ermittelter, langfristig erzielbarer Objektwert der Bank.","answer":"Vorsichtig ermittelter, langfristig erzielbarer Objektwert der Bank. Der Beleihungswert ist ein von der Bank vorsichtig und nachhaltig ermittelter Sicherheitenwert, der vom Kaufpreis oder aktuellen Marktwert abweichen kann. Er bildet die Basis für den Beleihungsauslauf.","url":"/lexikon/beleihungswert/","keywords":["beleihungswert","vorsichtig","ermittelter","langfristig","erzielbarer","objektwert","bank","ein","nachhaltig","sicherheitenwert","vom","kaufpreis","aktuellen","marktwert","abweichen","bildet","basis","beleihungsauslauf"]},{"kind":"lexicon","id":"bereitstellungszins","title":"Bereitstellungszins","category":"Finanzierung","summary":"Zins auf noch nicht abgerufene Darlehensteile nach einer Freiphase.","answer":"Zins auf noch nicht abgerufene Darlehensteile nach einer Freiphase. Bereitstellungszinsen sind Entgelte auf noch nicht abgerufene Darlehensteile nach Ablauf der bereitstellungszinsfreien Zeit. Sie sind besonders bei Neubau, Bauträgerzahlung und längeren Sanierungsphasen relevant.","url":"/lexikon/bereitstellungszins/","keywords":["bereitstellungszins","zins","noch","abgerufene","darlehensteile","nach","freiphase","bereitstellungszinsen","entgelte","ablauf","bereitstellungszinsfreien","zeit","sie","besonders","neubau","bauträgerzahlung","längeren","sanierungsphasen","relevant"]},{"kind":"lexicon","id":"betriebskosten","title":"Betriebskosten","category":"Vermietung","summary":"Laufende Kosten des bestimmungsgemäßen Gebrauchs.","answer":"Laufende Kosten des bestimmungsgemäßen Gebrauchs. Betriebskosten sind laufende Kosten des bestimmungsgemäßen Gebrauchs eines Gebäudes/Grundstücks. Welche Positionen auf Wohnraummieter umgelegt werden können, richtet sich nach Betriebskostenverordnung und wirksamer mietvertraglicher Vereinbarung.","url":"/lexikon/betriebskosten/","keywords":["betriebskosten","laufende","kosten","bestimmungsgemäßen","gebrauchs","gebäudes","grundstücks","welche","positionen","wohnraummieter","umgelegt","können","richtet","nach","betriebskostenverordnung","wirksamer","mietvertraglicher","vereinbarung"]},{"kind":"lexicon","id":"bewirtschaftungskosten","title":"Bewirtschaftungskosten","category":"Immobilienkauf","summary":"Kosten für Verwaltung, Betrieb, Instandhaltung und Mietausfall.","answer":"Kosten für Verwaltung, Betrieb, Instandhaltung und Mietausfall. Bewirtschaftungskosten sind laufende Kosten der Nutzung und Verwaltung eines Grundstücks, etwa Verwaltung, Instandhaltung und Mietausfallwagnis nach der jeweiligen Bewertungsdefinition. Sie reduzieren den nachhaltig verfügbaren Ertrag.","url":"/lexikon/bewirtschaftungskosten/","keywords":["bewirtschaftungskosten","kosten","verwaltung","betrieb","instandhaltung","mietausfall","laufende","nutzung","grundstücks","etwa","mietausfallwagnis","nach","jeweiligen","bewertungsdefinition","sie","reduzieren","nachhaltig","verfügbaren","ertrag"]},{"kind":"lexicon","id":"bodenrichtwert","title":"Bodenrichtwert","category":"Immobilienkauf","summary":"Durchschnittlicher Bodenwert eines räumlich abgegrenzten Richtwertgebiets.","answer":"Durchschnittlicher Bodenwert eines räumlich abgegrenzten Richtwertgebiets. Bodenrichtwert ist ein durchschnittlicher Lagewert des Bodens für eine Bodenrichtwertzone. Er ist kein verbindlicher Einzelgrundstückswert; Nutzung, Größe, Zuschnitt, Erschließung und weitere Merkmale können Anpassungen erforderlich machen.","url":"/lexikon/bodenrichtwert/","keywords":["bodenrichtwert","durchschnittlicher","bodenwert","räumlich","abgegrenzten","richtwertgebiets","ein","lagewert","bodens","bodenrichtwertzone","kein","verbindlicher","einzelgrundstückswert","nutzung","größe","zuschnitt","erschließung","weitere","merkmale","können","anpassungen","erforderlich","machen"]},{"kind":"lexicon","id":"bodenwert","title":"Bodenwert","category":"Immobilienkauf","summary":"Wert des unbebauten Grundstücks.","answer":"Wert des unbebauten Grundstücks. Bodenwert ist der Wert des Grundstücksbodens ohne Gebäude. Er kann aus geeigneten Vergleichsdaten oder Bodenrichtwerten unter objektspezifischen Anpassungen abgeleitet werden.","url":"/lexikon/bodenwert/","keywords":["bodenwert","wert","unbebauten","grundstücks","grundstücksbodens","ohne","gebäude","aus","geeigneten","vergleichsdaten","bodenrichtwerten","unter","objektspezifischen","anpassungen","abgeleitet"]},{"kind":"lexicon","id":"bonitat","title":"Bonität","category":"Finanzierung","summary":"Einschätzung der Fähigkeit und Bereitschaft, Verpflichtungen zu erfüllen.","answer":"Einschätzung der Fähigkeit und Bereitschaft, Verpflichtungen zu erfüllen. Bonität beschreibt die Fähigkeit und Bereitschaft eines Schuldners, finanzielle Verpflichtungen vertragsgemäß zu erfüllen. Banken beurteilen dafür Einkommen, Vermögen, Verpflichtungen, Zahlungsverhalten und weitere Risikomerkmale.","url":"/lexikon/bonitat/","keywords":["bonität","einschätzung","fähigkeit","bereitschaft","verpflichtungen","erfüllen","beschreibt","schuldners","finanzielle","vertragsgemäß","banken","beurteilen","dafür","einkommen","vermögen","zahlungsverhalten","weitere","risikomerkmale"]},{"kind":"lexicon","id":"bruttogrundflache","title":"Bruttogrundfläche","category":"Immobilienkauf","summary":"Gesamtheit bestimmter Grundflächen eines Bauwerks nach Norm.","answer":"Gesamtheit bestimmter Grundflächen eines Bauwerks nach Norm. Die Bruttogrundfläche ist eine Flächengröße aus dem Bau-/Bewertungsbereich und umfasst deutlich mehr als die Wohnfläche, unter anderem konstruktive Flächen. Sie ist für €/m²-Wohnungsvergleiche nicht austauschbar mit Wohnfläche.","url":"/lexikon/bruttogrundflache/","keywords":["bruttogrundfläche","gesamtheit","bestimmter","grundflächen","bauwerks","nach","norm","flächengröße","aus","bau-","bewertungsbereich","umfasst","deutlich","mehr","wohnfläche","unter","anderem","konstruktive","flächen","sie","-wohnungsvergleiche","austauschbar"]},{"kind":"lexicon","id":"bruttomietrendite","title":"Bruttomietrendite","category":"Kapitalanlage","summary":"Jahresnettokaltmiete geteilt durch Kaufpreis.","answer":"Jahresnettokaltmiete geteilt durch Kaufpreis. Die Bruttomietrendite ist eine schnelle Screeningkennzahl aus Jahresnettokaltmiete und Kaufpreis. Sie berücksichtigt weder Kaufnebenkosten noch laufende Eigentümerkosten oder Finanzierung.","url":"/lexikon/bruttomietrendite/","keywords":["bruttomietrendite","jahresnettokaltmiete","geteilt","durch","kaufpreis","schnelle","screeningkennzahl","aus","sie","berücksichtigt","weder","kaufnebenkosten","noch","laufende","eigentümerkosten","finanzierung"]},{"kind":"lexicon","id":"capex","title":"Capex","category":"Kapitalanlage","summary":"Größere, wert- oder nutzungsdauerrelevante Investitionen.","answer":"Größere, wert- oder nutzungsdauerrelevante Investitionen. Größere, wert- oder nutzungsdauerrelevante Investitionen. Capex ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/capex/","keywords":["capex","größere","wert-","nutzungsdauerrelevante","investitionen","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"cash-on-cash-rendite","title":"Cash-on-Cash-Rendite","category":"Kapitalanlage","summary":"Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital.","answer":"Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital. Laufender Cashflow im Verhältnis zum eingesetzten Eigenkapital. Cash-on-Cash-Rendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/cash-on-cash-rendite/","keywords":["cash-on-cash-rendite","laufender","cashflow","verhältnis","zum","eingesetzten","eigenkapital","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"cashflow","title":"Cashflow","category":"Kapitalanlage","summary":"Liquiditätsüberschuss oder -bedarf einer Periode.","answer":"Liquiditätsüberschuss oder -bedarf einer Periode. Cashflow bildet tatsächliche Ein- und Auszahlungen ab. Bei Immobilien sollte zwischen operativem Cashflow vor Finanzierung und Cashflow nach Kapitaldienst unterschieden werden. Tilgung belastet den Cashflow, ist aber gleichzeitig Vermögensumschichtung in das Objekt.","url":"/lexikon/cashflow/","keywords":["cashflow","liquiditätsüberschuss","-bedarf","periode","bildet","tatsächliche","ein-","auszahlungen","immobilien","sollte","zwischen","operativem","vor","finanzierung","nach","kapitaldienst","unterschieden","tilgung","belastet","aber","gleichzeitig","vermögensumschichtung","objekt"]},{"kind":"lexicon","id":"courtage","title":"Courtage","category":"Immobilienkauf","summary":"Maklervergütung.","answer":"Maklervergütung. Courtage ist die erfolgsabhängige Maklervergütung. Bei Kaufverträgen über Wohnungen und Einfamilienhäuser mit Verbraucherbeteiligung greifen die besonderen §§ 656a–656d BGB: Bei Doppeltätigkeit müssen sich beide Parteien in gleicher Höhe verpflichten; bei einseitigem Maklerauftrag kann eine Kostenabwälzung auf die andere Partei nur unter den gesetzlichen Voraussetzungen erfolgen. Diese Sonderregeln gelten nicht automatisch für Mehrfamilienhäuser, Gewerbeimmobilien oder Grundstücke. Eine allgemeine gesetzliche Provisionsobergrenze je Bundesland für Immobilienverkäufe existiert nicht; regionale Marktüblichkeiten sind keine gesetzlichen Höchstsätze.","url":"/lexikon/courtage/","keywords":["courtage","maklervergütung","erfolgsabhängige","kaufverträgen","über","wohnungen","einfamilienhäuser","verbraucherbeteiligung","greifen","besonderen","656a","656d","bgb","doppeltätigkeit","müssen","beide","parteien","gleicher","höhe","verpflichten","einseitigem","maklerauftrag","kostenabwälzung","andere","partei","nur","unter","gesetzlichen","voraussetzungen","erfolgen"]},{"kind":"lexicon","id":"debt-service","title":"Debt Service","category":"Immobilienkauf","summary":"Summe aus Zins und Tilgung.","answer":"Summe aus Zins und Tilgung. Debt Service beziehungsweise Kapitaldienst umfasst die periodischen Zahlungen an Fremdkapitalgeber, typischerweise Zins und Tilgung. Bei endfälligen oder variabel strukturierten Darlehen kann der Zahlungsstrom abweichen.","url":"/lexikon/debt-service/","keywords":["debt","service","summe","aus","zins","tilgung","beziehungsweise","kapitaldienst","umfasst","periodischen","zahlungen","fremdkapitalgeber","typischerweise","endfälligen","variabel","strukturierten","darlehen","zahlungsstrom","abweichen"]},{"kind":"lexicon","id":"dscr","title":"DSCR","category":"Finanzierung","summary":"Verhältnis des zur Verfügung stehenden Überschusses zum Schuldendienst.","answer":"Verhältnis des zur Verfügung stehenden Überschusses zum Schuldendienst. Der Debt Service Coverage Ratio misst, wie oft ein definierter verfügbarer Ertrag den Kapitaldienst aus Zins und Tilgung deckt. Die Aussage hängt stark davon ab, welche Ergebnisgröße im Zähler verwendet wird.","url":"/lexikon/dscr/","keywords":["dscr","verhältnis","zur","verfügung","stehenden","überschusses","zum","schuldendienst","debt","service","coverage","ratio","misst","wie","oft","ein","definierter","verfügbarer","ertrag","kapitaldienst","aus","zins","tilgung","deckt","aussage","hängt","stark","davon","welche","ergebnisgröße"]},{"kind":"lexicon","id":"due-diligence","title":"Due Diligence","category":"Immobilienkauf","summary":"Systematische Prüfung eines Investments.","answer":"Systematische Prüfung eines Investments. Due Diligence ist die strukturierte Prüfung einer Transaktion vor Abschluss. Bei Immobilien umfasst sie je nach Objekt rechtliche, technische, wirtschaftliche, steuerliche und finanzielle Aspekte.","url":"/lexikon/due-diligence/","keywords":["due","diligence","systematische","prüfung","investments","strukturierte","transaktion","vor","abschluss","immobilien","umfasst","sie","nach","objekt","rechtliche","technische","wirtschaftliche","steuerliche","finanzielle","aspekte"]},{"kind":"lexicon","id":"eigenkapital","title":"Eigenkapital","category":"Immobilienkauf","summary":"Eigene Mittel, die in Kauf und Nebenkosten eingebracht werden.","answer":"Eigene Mittel, die in Kauf und Nebenkosten eingebracht werden. Eigenkapital umfasst die für den Erwerb eingesetzten eigenen Mittel. Mehr Eigenkapital reduziert Darlehen und kann den Beleihungsauslauf senken; dadurch kann sich die Bankkondition verbessern. Gleichzeitig sinkt die frei verfügbare Liquiditätsreserve.","url":"/lexikon/eigenkapital/","keywords":["eigenkapital","eigene","mittel","kauf","nebenkosten","eingebracht","umfasst","erwerb","eingesetzten","eigenen","mehr","reduziert","darlehen","beleihungsauslauf","senken","dadurch","bankkondition","verbessern","gleichzeitig","sinkt","frei","verfügbare","liquiditätsreserve"]},{"kind":"lexicon","id":"eigenkapitalrendite","title":"Eigenkapitalrendite","category":"Kapitalanlage","summary":"Vermögenseffekt oder Ertrag im Verhältnis zum eingesetzten Eigenkapital.","answer":"Vermögenseffekt oder Ertrag im Verhältnis zum eingesetzten Eigenkapital. Eigenkapitalrendite setzt einen definierten Ertrag ins Verhältnis zum eingesetzten Eigenkapital. Cashflow, Tilgung und Wertänderung sollten getrennt ausgewiesen werden, weil sie wirtschaftlich unterschiedliche Komponenten sind.","url":"/lexikon/eigenkapitalrendite/","keywords":["eigenkapitalrendite","vermögenseffekt","ertrag","verhältnis","zum","eingesetzten","eigenkapital","setzt","einen","definierten","ins","cashflow","tilgung","wertänderung","sollten","getrennt","ausgewiesen","weil","sie","wirtschaftlich","unterschiedliche","komponenten"]},{"kind":"lexicon","id":"erbbaurecht","title":"Erbbaurecht","category":"Immobilienkauf","summary":"Zeitlich befristetes Recht, auf fremdem Grund ein Bauwerk zu haben.","answer":"Zeitlich befristetes Recht, auf fremdem Grund ein Bauwerk zu haben. Beim Erbbaurecht werden Gebäude und Grundstückseigentum rechtlich getrennt: Der Erbbauberechtigte nutzt das Grundstück für eine bestimmte Laufzeit und zahlt typischerweise Erbbauzins. Restlaufzeit, Anpassungsklauseln und Heimfallregelungen beeinflussen Wert und Finanzierung.","url":"/lexikon/erbbaurecht/","keywords":["erbbaurecht","zeitlich","befristetes","recht","fremdem","grund","ein","bauwerk","haben","beim","gebäude","grundstückseigentum","rechtlich","getrennt","erbbauberechtigte","nutzt","grundstück","bestimmte","laufzeit","zahlt","typischerweise","erbbauzins","restlaufzeit","anpassungsklauseln","heimfallregelungen","beeinflussen","wert","finanzierung"]},{"kind":"lexicon","id":"erbbauzins","title":"Erbbauzins","category":"Finanzierung","summary":"Regelmäßiges Entgelt für ein Erbbaurecht.","answer":"Regelmäßiges Entgelt für ein Erbbaurecht. Erbbauzins ist das regelmäßig zu zahlende Entgelt des Erbbauberechtigten an den Grundstückseigentümer. Höhe und Anpassungsmechanismus ergeben sich aus dem Erbbaurechtsvertrag.","url":"/lexikon/erbbauzins/","keywords":["erbbauzins","regelmäßiges","entgelt","ein","erbbaurecht","regelmäßig","zahlende","erbbauberechtigten","grundstückseigentümer","höhe","anpassungsmechanismus","ergeben","aus","erbbaurechtsvertrag"]},{"kind":"lexicon","id":"erhaltungsrucklage","title":"Erhaltungsrücklage","category":"Vermietung","summary":"Von einer WEG angesparte Mittel für Gemeinschaftseigentum.","answer":"Von einer WEG angesparte Mittel für Gemeinschaftseigentum. Die Erhaltungsrücklage ist Gemeinschaftsvermögen der WEG für künftige Maßnahmen am Gemeinschaftseigentum. Der rechnerisch auf eine Wohnung entfallende Anteil ist kein frei auszahlbares Guthaben des einzelnen Eigentümers.","url":"/lexikon/erhaltungsrucklage/","keywords":["erhaltungsrücklage","weg","angesparte","mittel","gemeinschaftseigentum","gemeinschaftsvermögen","künftige","maßnahmen","rechnerisch","wohnung","entfallende","anteil","kein","frei","auszahlbares","guthaben","einzelnen","eigentümers"]},{"kind":"lexicon","id":"ertragswert","title":"Ertragswert","category":"Immobilienkauf","summary":"Aus nachhaltig erzielbaren Erträgen abgeleiteter Wert.","answer":"Aus nachhaltig erzielbaren Erträgen abgeleiteter Wert. Der Ertragswert ist ein im Ertragswertverfahren abgeleiteter Grundstückswert, der wesentlich auf nachhaltig erzielbaren Erträgen, Bewirtschaftungskosten, Liegenschaftszins und Restnutzungsdauer beruht.","url":"/lexikon/ertragswert/","keywords":["ertragswert","aus","nachhaltig","erzielbaren","erträgen","abgeleiteter","wert","ein","ertragswertverfahren","grundstückswert","wesentlich","bewirtschaftungskosten","liegenschaftszins","restnutzungsdauer","beruht"]},{"kind":"lexicon","id":"exit","title":"Exit","category":"Kapitalanlage","summary":"Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment.","answer":"Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment. Geplanter Verkauf oder anderweitiger Ausstieg aus dem Investment. Exit ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/exit/","keywords":["exit","geplanter","verkauf","anderweitiger","ausstieg","aus","investment","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"exit-faktor","title":"Exit-Faktor","category":"Kapitalanlage","summary":"Beim Verkauf angenommener Kaufpreisfaktor.","answer":"Beim Verkauf angenommener Kaufpreisfaktor. Beim Verkauf angenommener Kaufpreisfaktor. Exit-Faktor ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/exit-faktor/","keywords":["exit-faktor","beim","verkauf","angenommener","kaufpreisfaktor","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"finanzierungsquote","title":"Finanzierungsquote","category":"Finanzierung","summary":"Anteil einer gewählten Bezugsgröße, der durch Darlehen finanziert wird.","answer":"Anteil einer gewählten Bezugsgröße, der durch Darlehen finanziert wird. Die Finanzierungsquote setzt die Darlehenssumme ins Verhältnis zu einer definierten Investitionsbasis, meist Kaufpreis oder Gesamtinvestition. Sie ist von LTV und Beleihungsauslauf zu unterscheiden, weil dort andere Wertansätze im Nenner stehen können.","url":"/lexikon/finanzierungsquote/","keywords":["finanzierungsquote","anteil","gewählten","bezugsgröße","durch","darlehen","finanziert","setzt","darlehenssumme","ins","verhältnis","definierten","investitionsbasis","meist","kaufpreis","gesamtinvestition","sie","ltv","beleihungsauslauf","unterscheiden","weil","dort","andere","wertansätze","nenner","stehen","können"]},{"kind":"lexicon","id":"flurstuck","title":"Flurstück","category":"Immobilienkauf","summary":"Amtlich vermessener Teil der Erdoberfläche.","answer":"Amtlich vermessener Teil der Erdoberfläche. Ein Flurstück ist die kleinste im Liegenschaftskataster geführte Buchungseinheit eines Grundstücks. Ein Grundstück im Grundbuch kann aus einem oder mehreren Flurstücken bestehen.","url":"/lexikon/flurstuck/","keywords":["flurstück","amtlich","vermessener","teil","erdoberfläche","ein","kleinste","liegenschaftskataster","geführte","buchungseinheit","grundstücks","grundstück","grundbuch","aus","einem","mehreren","flurstücken","bestehen"]},{"kind":"lexicon","id":"forward-darlehen","title":"Forward-Darlehen","category":"Finanzierung","summary":"Heute vereinbarte Anschlussfinanzierung mit späterer Auszahlung.","answer":"Heute vereinbarte Anschlussfinanzierung mit späterer Auszahlung. Ein Forward-Darlehen ist eine heute vereinbarte Anschlussfinanzierung mit zukünftiger Auszahlung. Der Darlehensnehmer sichert den Zins vor Ende der bestehenden Bindung; dafür kann ein Forward-Aufschlag anfallen. Vorlaufzeiten von mehreren Jahren, häufig bis etwa fünf Jahre, sind marktüblich, aber bankabhängig.","url":"/lexikon/forward-darlehen/","keywords":["forward-darlehen","heute","vereinbarte","anschlussfinanzierung","späterer","auszahlung","ein","zukünftiger","darlehensnehmer","sichert","zins","vor","ende","bestehenden","bindung","dafür","forward-aufschlag","anfallen","vorlaufzeiten","mehreren","jahren","häufig","bis","etwa","fünf","jahre","marktüblich","aber","bankabhängig"]},{"kind":"lexicon","id":"fremdkapitalhebel","title":"Fremdkapitalhebel","category":"Kapitalanlage","summary":"Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital.","answer":"Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital. Veränderung der Eigenkapitalrendite durch Einsatz von Fremdkapital. Fremdkapitalhebel ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/fremdkapitalhebel/","keywords":["fremdkapitalhebel","veränderung","eigenkapitalrendite","durch","einsatz","fremdkapital","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"gebaudeanteil","title":"Gebäudeanteil","category":"Immobilienkauf","summary":"Anteil des Kaufpreises, der dem Gebäude statt Grund und Boden zugeordnet wird.","answer":"Anteil des Kaufpreises, der dem Gebäude statt Grund und Boden zugeordnet wird. Gebäudeanteil bezeichnet den Teil des Gesamtwerts beziehungsweise der Anschaffungskosten, der wirtschaftlich auf das Gebäude entfällt. Für die Gebäude-AfA ist die Abgrenzung zum nicht abschreibbaren Grund und Boden zentral.","url":"/lexikon/gebaudeanteil/","keywords":["gebäudeanteil","anteil","kaufpreises","gebäude","statt","grund","boden","zugeordnet","bezeichnet","teil","gesamtwerts","beziehungsweise","anschaffungskosten","wirtschaftlich","entfällt","gebäude-afa","abgrenzung","zum","abschreibbaren","zentral"]},{"kind":"lexicon","id":"gemeinschaftseigentum","title":"Gemeinschaftseigentum","category":"Immobilienkauf","summary":"Teile einer WEG, die allen Eigentümern gemeinsam gehören.","answer":"Teile einer WEG, die allen Eigentümern gemeinsam gehören. Gemeinschaftseigentum sind Gebäudeteile und Grundstücksbestandteile, die allen Wohnungseigentümern gemeinschaftlich gehören oder zwingend gemeinschaftlich sein müssen. Maßnahmen werden über die WEG entschieden und finanziert.","url":"/lexikon/gemeinschaftseigentum/","keywords":["gemeinschaftseigentum","teile","weg","allen","eigentümern","gemeinsam","gehören","gebäudeteile","grundstücksbestandteile","wohnungseigentümern","gemeinschaftlich","zwingend","sein","müssen","maßnahmen","über","entschieden","finanziert"]},{"kind":"lexicon","id":"gesamtinvestition","title":"Gesamtinvestition","category":"Immobilienkauf","summary":"Kaufpreis plus Nebenkosten und Anfangsinvestitionen.","answer":"Kaufpreis plus Nebenkosten und Anfangsinvestitionen. Gesamtinvestition umfasst den gesamten wirtschaftlich eingesetzten Kapitalbetrag für Erwerb und Herstellung der Nutzbarkeit, nicht nur den notariellen Kaufpreis.","url":"/lexikon/gesamtinvestition/","keywords":["gesamtinvestition","kaufpreis","plus","nebenkosten","anfangsinvestitionen","umfasst","gesamten","wirtschaftlich","eingesetzten","kapitalbetrag","erwerb","herstellung","nutzbarkeit","nur","notariellen"]},{"kind":"lexicon","id":"grundbuch","title":"Grundbuch","category":"Immobilienkauf","summary":"Öffentliches Register der Grundstücksrechte.","answer":"Öffentliches Register der Grundstücksrechte. Das Grundbuch dokumentiert Eigentum und dingliche Rechte an Grundstücken. Abteilung I enthält Eigentümer, Abteilung II unter anderem Lasten/Beschränkungen und Abteilung III Grundpfandrechte.","url":"/lexikon/grundbuch/","keywords":["grundbuch","öffentliches","register","grundstücksrechte","dokumentiert","eigentum","dingliche","rechte","grundstücken","abteilung","enthält","eigentümer","unter","anderem","lasten","beschränkungen","iii","grundpfandrechte"]},{"kind":"lexicon","id":"grunderwerbsteuer","title":"Grunderwerbsteuer","category":"Steuern","summary":"Landessteuer beim Erwerb inländischer Grundstücke.","answer":"Landessteuer beim Erwerb inländischer Grundstücke. Grunderwerbsteuer fällt bei steuerbaren Grundstückserwerben an und wird von den Ländern mit unterschiedlichen Steuersätzen erhoben. Sie ist regelmäßig nicht Teil der Gebäude-AfA, sondern wird anteilig den Anschaffungskosten von Grund/Boden und Gebäude zugerechnet.","url":"/lexikon/grunderwerbsteuer/","keywords":["grunderwerbsteuer","landessteuer","beim","erwerb","inländischer","grundstücke","fällt","steuerbaren","grundstückserwerben","ländern","unterschiedlichen","steuersätzen","erhoben","sie","regelmäßig","teil","gebäude-afa","sondern","anteilig","anschaffungskosten","grund","boden","gebäude","zugerechnet"]},{"kind":"lexicon","id":"grundschuld","title":"Grundschuld","category":"Finanzierung","summary":"Grundpfandrecht zur Kreditsicherung.","answer":"Grundpfandrecht zur Kreditsicherung. Die Grundschuld ist ein dingliches Sicherungsrecht im Grundbuch, das Banken typischerweise zur Absicherung eines Immobiliendarlehens nutzen. Sie ist rechtlich vom Darlehen getrennt und bleibt ohne Löschung auch nach Tilgung im Grundbuch bestehen.","url":"/lexikon/grundschuld/","keywords":["grundschuld","grundpfandrecht","zur","kreditsicherung","ein","dingliches","sicherungsrecht","grundbuch","banken","typischerweise","absicherung","immobiliendarlehens","nutzen","sie","rechtlich","vom","darlehen","getrennt","bleibt","ohne","löschung","nach","tilgung","bestehen"]},{"kind":"lexicon","id":"grundsteuer","title":"Grundsteuer","category":"Steuern","summary":"Laufende Steuer auf Grundbesitz.","answer":"Laufende Steuer auf Grundbesitz. Grundsteuer ist eine laufende Objektsteuer auf Grundbesitz. Bei vermietetem Wohnraum kann sie bei wirksamer Betriebskostenvereinbarung grundsätzlich umlagefähig sein.","url":"/lexikon/grundsteuer/","keywords":["grundsteuer","laufende","steuer","grundbesitz","objektsteuer","vermietetem","wohnraum","sie","wirksamer","betriebskostenvereinbarung","grundsätzlich","umlagefähig","sein"]},{"kind":"lexicon","id":"hausgeld","title":"Hausgeld","category":"Vermietung","summary":"Monatliche Vorauszahlung des Wohnungseigentümers an die WEG.","answer":"Monatliche Vorauszahlung des Wohnungseigentümers an die WEG. Hausgeld ist der monatliche Vorschuss eines Wohnungseigentümers an die WEG. Es umfasst typischerweise Betriebskosten, Verwaltung und Zuführung zur Erhaltungsrücklage; deshalb ist es nicht mit „Nebenkosten des Mieters“ gleichzusetzen.","url":"/lexikon/hausgeld/","keywords":["hausgeld","monatliche","vorauszahlung","wohnungseigentümers","weg","vorschuss","umfasst","typischerweise","betriebskosten","verwaltung","zuführung","zur","erhaltungsrücklage","deshalb","nebenkosten","mieters","gleichzusetzen"]},{"kind":"lexicon","id":"hebelwirkung","title":"Hebelwirkung","category":"Kapitalanlage","summary":"Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko.","answer":"Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko. Wirkung von Fremdkapital auf Eigenkapitalergebnis und Risiko. Hebelwirkung ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/hebelwirkung/","keywords":["hebelwirkung","wirkung","fremdkapital","eigenkapitalergebnis","risiko","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"indexmiete","title":"Indexmiete","category":"Vermietung","summary":"Miete mit vertraglicher Kopplung an den Verbraucherpreisindex.","answer":"Miete mit vertraglicher Kopplung an den Verbraucherpreisindex. Bei der Indexmiete wird die Mietentwicklung an den vom Statistischen Bundesamt ermittelten Verbraucherpreisindex gekoppelt. Die Miete ändert sich nicht automatisch; die gesetzlich vorgeschriebene Erklärung ist erforderlich. Während der Geltung muss die Miete grundsätzlich mindestens ein Jahr unverändert bleiben.","url":"/lexikon/indexmiete/","keywords":["indexmiete","miete","vertraglicher","kopplung","verbraucherpreisindex","mietentwicklung","vom","statistischen","bundesamt","ermittelten","gekoppelt","ändert","automatisch","gesetzlich","vorgeschriebene","erklärung","erforderlich","während","geltung","muss","grundsätzlich","mindestens","ein","jahr","unverändert","bleiben"]},{"kind":"lexicon","id":"instandhaltung","title":"Instandhaltung","category":"Immobilienkauf","summary":"Maßnahmen zum Erhalt des bestimmungsgemäßen Zustands.","answer":"Maßnahmen zum Erhalt des bestimmungsgemäßen Zustands. Instandhaltung umfasst Maßnahmen, die den ordnungsgemäßen Zustand erhalten und Verschleiß vorbeugen. Sie ist von Modernisierung und größerer Instandsetzung zu unterscheiden.","url":"/lexikon/instandhaltung/","keywords":["instandhaltung","maßnahmen","zum","erhalt","bestimmungsgemäßen","zustands","umfasst","ordnungsgemäßen","zustand","erhalten","verschleiß","vorbeugen","sie","modernisierung","größerer","instandsetzung","unterscheiden"]},{"kind":"lexicon","id":"instandhaltungsstau","title":"Instandhaltungsstau","category":"Immobilienkauf","summary":"Aufgeschobener Erhaltungsbedarf.","answer":"Aufgeschobener Erhaltungsbedarf. Instandhaltungsstau bezeichnet aufgeschobene notwendige Erhaltungsmaßnahmen. Er ist ein wirtschaftliches Risiko, weil vermeintlich niedrige Kaufpreise durch kurzfristig erforderlichen CapEx neutralisiert werden können.","url":"/lexikon/instandhaltungsstau/","keywords":["instandhaltungsstau","aufgeschobener","erhaltungsbedarf","bezeichnet","aufgeschobene","notwendige","erhaltungsmaßnahmen","ein","wirtschaftliches","risiko","weil","vermeintlich","niedrige","kaufpreise","durch","kurzfristig","erforderlichen","capex","neutralisiert","können"]},{"kind":"lexicon","id":"instandsetzung","title":"Instandsetzung","category":"Immobilienkauf","summary":"Wiederherstellung eines ordnungsgemäßen Zustands.","answer":"Wiederherstellung eines ordnungsgemäßen Zustands. Instandsetzung stellt einen bereits beeinträchtigten ordnungsgemäßen Zustand wieder her. Sie unterscheidet sich von vorbeugender Instandhaltung und von wert-/gebrauchserhöhender Modernisierung.","url":"/lexikon/instandsetzung/","keywords":["instandsetzung","wiederherstellung","ordnungsgemäßen","zustands","stellt","einen","bereits","beeinträchtigten","zustand","wieder","her","sie","unterscheidet","vorbeugender","instandhaltung","wert-","gebrauchserhöhender","modernisierung"]},{"kind":"lexicon","id":"irr","title":"IRR","category":"Kapitalanlage","summary":"Interner Zinsfuß eines Zahlungsstroms.","answer":"Interner Zinsfuß eines Zahlungsstroms. Die Internal Rate of Return ist der Diskontsatz, bei dem der Kapitalwert aller Ein- und Auszahlungen null wird. Sie berücksichtigt das Timing der Zahlungsströme und ist stark von Haltedauer und Exitannahme abhängig.","url":"/lexikon/irr/","keywords":["irr","interner","zinsfuß","zahlungsstroms","internal","rate","return","diskontsatz","kapitalwert","aller","ein-","auszahlungen","null","sie","berücksichtigt","timing","zahlungsströme","stark","haltedauer","exitannahme","abhängig"]},{"kind":"lexicon","id":"jahresnettokaltmiete","title":"Jahresnettokaltmiete","category":"Vermietung","summary":"Summe der Nettokaltmieten eines Jahres.","answer":"Summe der Nettokaltmieten eines Jahres. Jahresnettokaltmiete (JNKM) ist die Summe der vertraglichen Nettokaltmieten eines Jahres ohne umlagefähige Betriebskosten. Sie ist zentrale Basis für Faktor- und Bruttorenditerechnungen.","url":"/lexikon/jahresnettokaltmiete/","keywords":["jahresnettokaltmiete","summe","nettokaltmieten","jahres","jnkm","vertraglichen","ohne","umlagefähige","betriebskosten","sie","zentrale","basis","faktor-","bruttorenditerechnungen"]},{"kind":"lexicon","id":"kapitaldienst","title":"Kapitaldienst","category":"Finanzierung","summary":"Zins und Tilgung eines Darlehens.","answer":"Zins und Tilgung eines Darlehens. Kapitaldienst ist die Summe aus Zins- und Tilgungszahlungen eines Darlehens in einer Periode. Er bestimmt die laufende Liquiditätsbelastung und ist zentral für DSCR und Tragfähigkeitsrechnungen.","url":"/lexikon/kapitaldienst/","keywords":["kapitaldienst","zins","tilgung","darlehens","summe","aus","zins-","tilgungszahlungen","periode","bestimmt","laufende","liquiditätsbelastung","zentral","dscr","tragfähigkeitsrechnungen"]},{"kind":"lexicon","id":"kapitalisierungszins","title":"Kapitalisierungszins","category":"Finanzierung","summary":"Zinssatz zur Umrechnung künftiger Erträge in einen heutigen Wert.","answer":"Zinssatz zur Umrechnung künftiger Erträge in einen heutigen Wert. Kapitalisierungszins ist der Zinssatz, mit dem zukünftige Erträge in einen Barwert überführt werden. Je höher der Zinssatz bei gleichen Erträgen, desto niedriger der Barwert.","url":"/lexikon/kapitalisierungszins/","keywords":["kapitalisierungszins","zinssatz","zur","umrechnung","künftiger","erträge","einen","heutigen","wert","zukünftige","barwert","überführt","höher","gleichen","erträgen","desto","niedriger"]},{"kind":"lexicon","id":"kapitalwert","title":"Kapitalwert","category":"Kapitalanlage","summary":"Barwert aller Ein- und Auszahlungen abzüglich Anfangsinvestition.","answer":"Barwert aller Ein- und Auszahlungen abzüglich Anfangsinvestition. Der Kapitalwert ist die Summe der auf heute diskontierten zukünftigen Nettozahlungen abzüglich Anfangsinvestition. Positiv bedeutet: Die modellierten Zahlungsströme übertreffen die verwendete Renditeanforderung.","url":"/lexikon/kapitalwert/","keywords":["kapitalwert","barwert","aller","ein-","auszahlungen","abzüglich","anfangsinvestition","summe","heute","diskontierten","zukünftigen","nettozahlungen","positiv","bedeutet","modellierten","zahlungsströme","übertreffen","verwendete","renditeanforderung"]},{"kind":"lexicon","id":"kappungsgrenze","title":"Kappungsgrenze","category":"Immobilienkauf","summary":"Grenze für Mieterhöhungen innerhalb eines Zeitraums.","answer":"Grenze für Mieterhöhungen innerhalb eines Zeitraums. Die Kappungsgrenze begrenzt bei Mieterhöhungen nach § 558 BGB die Erhöhung innerhalb von drei Jahren zusätzlich zur ortsüblichen Vergleichsmiete. In bestimmten Gebieten kann die Grenze abgesenkt sein.","url":"/lexikon/kappungsgrenze/","keywords":["kappungsgrenze","grenze","mieterhöhungen","innerhalb","zeitraums","begrenzt","nach","558","bgb","erhöhung","drei","jahren","zusätzlich","zur","ortsüblichen","vergleichsmiete","bestimmten","gebieten","abgesenkt","sein"]},{"kind":"lexicon","id":"kaufnebenkosten","title":"Kaufnebenkosten","category":"Immobilienkauf","summary":"Zusätzliche Erwerbskosten neben dem Kaufpreis.","answer":"Zusätzliche Erwerbskosten neben dem Kaufpreis. Kaufnebenkosten umfassen insbesondere Grunderwerbsteuer, Notar/Grundbuch und gegebenenfalls Maklercourtage. Zusätzlich können Finanzierung, Gutachten, Renovierung oder Möblierung den tatsächlichen Kapitalbedarf erhöhen.","url":"/lexikon/kaufnebenkosten/","keywords":["kaufnebenkosten","zusätzliche","erwerbskosten","neben","kaufpreis","umfassen","insbesondere","grunderwerbsteuer","notar","grundbuch","gegebenenfalls","maklercourtage","zusätzlich","können","finanzierung","gutachten","renovierung","möblierung","tatsächlichen","kapitalbedarf","erhöhen"]},{"kind":"lexicon","id":"kaufpreisfaktor","title":"Kaufpreisfaktor","category":"Kapitalanlage","summary":"Kaufpreis geteilt durch Jahresnettokaltmiete.","answer":"Kaufpreis geteilt durch Jahresnettokaltmiete. Der Kaufpreisfaktor setzt Kaufpreis und Jahresnettokaltmiete ins Verhältnis. Er ist bei identischer Basis der Kehrwert der Bruttomietrendite und ignoriert Nebenkosten, Bewirtschaftung, Finanzierung und CapEx.","url":"/lexikon/kaufpreisfaktor/","keywords":["kaufpreisfaktor","kaufpreis","geteilt","durch","jahresnettokaltmiete","setzt","ins","verhältnis","identischer","basis","kehrwert","bruttomietrendite","ignoriert","nebenkosten","bewirtschaftung","finanzierung","capex"]},{"kind":"lexicon","id":"kreditwurdigkeitsprufung","title":"Kreditwürdigkeitsprüfung","category":"Immobilienkauf","summary":"Prüfung von Einkommen, Vermögen, Verpflichtungen und Zahlungsverhalten.","answer":"Prüfung von Einkommen, Vermögen, Verpflichtungen und Zahlungsverhalten. Die Kreditwürdigkeitsprüfung beurteilt, ob der Kreditnehmer die Verpflichtungen aus dem Darlehen voraussichtlich erfüllen kann. Bei Immobiliardarlehen werden persönliche Tragfähigkeit und Objekt-/Sicherheitenbewertung zusammengeführt.","url":"/lexikon/kreditwurdigkeitsprufung/","keywords":["kreditwürdigkeitsprüfung","prüfung","einkommen","vermögen","verpflichtungen","zahlungsverhalten","beurteilt","kreditnehmer","aus","darlehen","voraussichtlich","erfüllen","immobiliardarlehen","persönliche","tragfähigkeit","objekt-","sicherheitenbewertung","zusammengeführt"]},{"kind":"lexicon","id":"leerstand","title":"Leerstand","category":"Vermietung","summary":"Nicht vermietete Fläche oder Einheit.","answer":"Nicht vermietete Fläche oder Einheit. Leerstand ist der Zeitraum oder Anteil ohne zahlenden Nutzer. Wirtschaftlich muss zwischen kurzfristigem Vermietungsleerstand, strategischem Leerstand und strukturellem Leerstand unterschieden werden.","url":"/lexikon/leerstand/","keywords":["leerstand","vermietete","fläche","einheit","zeitraum","anteil","ohne","zahlenden","nutzer","wirtschaftlich","muss","zwischen","kurzfristigem","vermietungsleerstand","strategischem","strukturellem","unterschieden"]},{"kind":"lexicon","id":"liegenschaftszins","title":"Liegenschaftszins","category":"Finanzierung","summary":"Marktüblicher Zinssatz im Ertragswertverfahren.","answer":"Marktüblicher Zinssatz im Ertragswertverfahren. Der Liegenschaftszins ist ein marktbezogener Zinssatz in der Immobilienwertermittlung, der die marktübliche Verzinsung von Grundstücken bestimmter Art abbildet. Er ist keine Bankkondition und kein individueller Renditewunsch.","url":"/lexikon/liegenschaftszins/","keywords":["liegenschaftszins","marktüblicher","zinssatz","ertragswertverfahren","ein","marktbezogener","immobilienwertermittlung","marktübliche","verzinsung","grundstücken","bestimmter","art","abbildet","keine","bankkondition","kein","individueller","renditewunsch"]},{"kind":"lexicon","id":"liquiditatsreserve","title":"Liquiditätsreserve","category":"Immobilienkauf","summary":"Sofort verfügbare Mittel für Unvorhergesehenes.","answer":"Sofort verfügbare Mittel für Unvorhergesehenes. Liquiditätsreserve ist frei verfügbares Kapital für ungeplante Ausgaben, Leerstand, Reparaturen oder Finanzierungslücken. Sie sollte nicht mit langfristig gebundenem Eigenkapital oder WEG-Rücklagen verwechselt werden.","url":"/lexikon/liquiditatsreserve/","keywords":["liquiditätsreserve","sofort","verfügbare","mittel","unvorhergesehenes","frei","verfügbares","kapital","ungeplante","ausgaben","leerstand","reparaturen","finanzierungslücken","sie","sollte","langfristig","gebundenem","eigenkapital","weg-rücklagen","verwechselt"]},{"kind":"lexicon","id":"ltv","title":"LTV","category":"Finanzierung","summary":"Loan-to-Value: Darlehen im Verhältnis zu einem Objektwert.","answer":"Loan-to-Value: Darlehen im Verhältnis zu einem Objektwert. Loan-to-Value bezeichnet das Verhältnis von Darlehen zu einem definierten Objektwert. Im deutschen Bankgeschäft ist davon der Beleihungsauslauf auf Basis des Beleihungswerts zu unterscheiden. Für internationale Vergleiche muss immer geklärt werden, welcher Wert im Nenner steht.","url":"/lexikon/ltv/","keywords":["ltv","loan-to-value","darlehen","verhältnis","einem","objektwert","bezeichnet","definierten","deutschen","bankgeschäft","davon","beleihungsauslauf","basis","beleihungswerts","unterscheiden","internationale","vergleiche","muss","immer","geklärt","welcher","wert","nenner","steht"]},{"kind":"lexicon","id":"maklerprovision","title":"Maklerprovision","category":"Immobilienkauf","summary":"Vergütung für die Vermittlungs- oder Nachweistätigkeit.","answer":"Vergütung für die Vermittlungs- oder Nachweistätigkeit. Maklerprovision ist die vertraglich vereinbarte Vergütung für den erfolgreichen Nachweis oder die Vermittlung. Für Verbraucher beim Kauf einer Wohnung oder eines Einfamilienhauses gelten besondere Regeln zur Verteilung der Maklerkosten; für andere Immobilienarten ist die konkrete Provisionsvereinbarung maßgeblich.","url":"/lexikon/maklerprovision/","keywords":["maklerprovision","vergütung","vermittlungs-","nachweistätigkeit","vertraglich","vereinbarte","erfolgreichen","nachweis","vermittlung","verbraucher","beim","kauf","wohnung","einfamilienhauses","gelten","besondere","regeln","zur","verteilung","maklerkosten","andere","immobilienarten","konkrete","provisionsvereinbarung","maßgeblich"]},{"kind":"lexicon","id":"mietausfall","title":"Mietausfall","category":"Immobilienkauf","summary":"Ausbleibender Mietertrag durch Leerstand oder Nichtzahlung.","answer":"Ausbleibender Mietertrag durch Leerstand oder Nichtzahlung. Mietausfall ist tatsächlich nicht vereinnahmte Sollmiete durch Leerstand, Zahlungsstörung oder Forderungsausfall. Er sollte bei Einzelobjekten möglichst aus konkretem Mieterrisiko und Vermietbarkeit statt nur pauschal geschätzt werden.","url":"/lexikon/mietausfall/","keywords":["mietausfall","ausbleibender","mietertrag","durch","leerstand","nichtzahlung","tatsächlich","vereinnahmte","sollmiete","zahlungsstörung","forderungsausfall","sollte","einzelobjekten","möglichst","aus","konkretem","mieterrisiko","vermietbarkeit","statt","nur","pauschal","geschätzt"]},{"kind":"lexicon","id":"mietbindung","title":"Mietbindung","category":"Immobilienkauf","summary":"Rechtliche Bindung von Miethöhe oder Belegung.","answer":"Rechtliche Bindung von Miethöhe oder Belegung. Mietbindung bezeichnet rechtliche Bindungen, die Miethöhe, Belegung oder Nutzung einschränken können, etwa im geförderten Wohnungsbau. Sie beeinflusst Ertrag und Verwertungsmöglichkeiten.","url":"/lexikon/mietbindung/","keywords":["mietbindung","rechtliche","bindung","miethöhe","belegung","bezeichnet","bindungen","nutzung","einschränken","können","etwa","geförderten","wohnungsbau","sie","beeinflusst","ertrag","verwertungsmöglichkeiten"]},{"kind":"lexicon","id":"mietpreisbremse","title":"Mietpreisbremse","category":"Immobilienkauf","summary":"Gesetzliche Begrenzung der Wiedervermietungsmiete in bestimmten Gebieten.","answer":"Gesetzliche Begrenzung der Wiedervermietungsmiete in bestimmten Gebieten. Die Mietpreisbremse begrenzt in ausgewiesenen Gebieten die zulässige Neuvertragsmiete grundsätzlich nach §§ 556d ff. BGB, vorbehaltlich gesetzlicher Ausnahmen und Vormietenregeln. Sie ist von der Kappungsgrenze im laufenden Mietverhältnis zu unterscheiden.","url":"/lexikon/mietpreisbremse/","keywords":["mietpreisbremse","gesetzliche","begrenzung","wiedervermietungsmiete","bestimmten","gebieten","begrenzt","ausgewiesenen","zulässige","neuvertragsmiete","grundsätzlich","nach","556d","bgb","vorbehaltlich","gesetzlicher","ausnahmen","vormietenregeln","sie","kappungsgrenze","laufenden","mietverhältnis","unterscheiden"]},{"kind":"lexicon","id":"mietrendite","title":"Mietrendite","category":"Kapitalanlage","summary":"Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis.","answer":"Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis. Mietertrag im Verhältnis zu einer Wert- oder Kostenbasis. Mietrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/mietrendite/","keywords":["mietrendite","mietertrag","verhältnis","wert-","kostenbasis","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"mietspiegel","title":"Mietspiegel","category":"Immobilienkauf","summary":"Übersicht ortsüblicher Vergleichsmieten.","answer":"Übersicht ortsüblicher Vergleichsmieten. Mietspiegel geben die ortsübliche Vergleichsmiete nach gesetzlichen Kriterien wieder. Sie dienen insbesondere als Begründungsmittel für Mieterhöhungen und sind von Portal-Angebotsmieten zu unterscheiden.","url":"/lexikon/mietspiegel/","keywords":["mietspiegel","übersicht","ortsüblicher","vergleichsmieten","geben","ortsübliche","vergleichsmiete","nach","gesetzlichen","kriterien","wieder","sie","dienen","insbesondere","begründungsmittel","mieterhöhungen","portal-angebotsmieten","unterscheiden"]},{"kind":"lexicon","id":"mietuberschuss","title":"Mietüberschuss","category":"Immobilienkauf","summary":"Miete abzüglich objektspezifischer laufender Kosten.","answer":"Miete abzüglich objektspezifischer laufender Kosten. Mietüberschuss ist der nach definierten laufenden Objektkosten verbleibende Mietertrag. Ob Finanzierung, Steuern oder Rücklagen enthalten sind, muss ausdrücklich definiert werden.","url":"/lexikon/mietuberschuss/","keywords":["mietüberschuss","miete","abzüglich","objektspezifischer","laufender","kosten","nach","definierten","laufenden","objektkosten","verbleibende","mietertrag","finanzierung","steuern","rücklagen","enthalten","muss","ausdrücklich","definiert"]},{"kind":"lexicon","id":"miteigentumsanteil","title":"Miteigentumsanteil","category":"Immobilienkauf","summary":"Rechnerischer Anteil am Gemeinschaftseigentum.","answer":"Rechnerischer Anteil am Gemeinschaftseigentum. Der Miteigentumsanteil beschreibt den Bruchteil, mit dem ein Wohnungseigentümer am Gemeinschaftseigentum beteiligt ist. Er kann für Kosten- und Stimmrechtsfragen relevant sein, soweit Gemeinschaftsordnung oder Gesetz nichts anderes regeln.","url":"/lexikon/miteigentumsanteil/","keywords":["miteigentumsanteil","rechnerischer","anteil","gemeinschaftseigentum","beschreibt","bruchteil","ein","wohnungseigentümer","beteiligt","kosten-","stimmrechtsfragen","relevant","sein","soweit","gemeinschaftsordnung","gesetz","nichts","anderes","regeln"]},{"kind":"lexicon","id":"modernisierung","title":"Modernisierung","category":"Immobilienkauf","summary":"Bauliche Verbesserung über reine Erhaltung hinaus.","answer":"Bauliche Verbesserung über reine Erhaltung hinaus. Modernisierung verbessert den Gebrauchswert, spart nachhaltig Energie/Wasser oder schafft neuen Wohnraum beziehungsweise erfüllt weitere gesetzliche Tatbestände. Sie ist von bloßer Erhaltung/Instandsetzung abzugrenzen, weil dies mietrechtlich und wirtschaftlich unterschiedliche Folgen hat.","url":"/lexikon/modernisierung/","keywords":["modernisierung","bauliche","verbesserung","über","reine","erhaltung","hinaus","verbessert","gebrauchswert","spart","nachhaltig","energie","wasser","schafft","neuen","wohnraum","beziehungsweise","erfüllt","weitere","gesetzliche","tatbestände","sie","bloßer","instandsetzung","abzugrenzen","weil","dies","mietrechtlich","wirtschaftlich","unterschiedliche"]},{"kind":"lexicon","id":"nachrangdarlehen","title":"Nachrangdarlehen","category":"Finanzierung","summary":"Darlehen, dessen Gläubiger im Rang hinter andere Gläubiger tritt.","answer":"Darlehen, dessen Gläubiger im Rang hinter andere Gläubiger tritt. Ein Nachrangdarlehen wird im Rang hinter vorrangigen Gläubigern bedient beziehungsweise besichert. Wegen des höheren Verlustrisikos ist es häufig teurer und wird von Banken bei der Gesamtfinanzierung gesondert bewertet.","url":"/lexikon/nachrangdarlehen/","keywords":["nachrangdarlehen","darlehen","dessen","gläubiger","rang","hinter","andere","tritt","ein","vorrangigen","gläubigern","bedient","beziehungsweise","besichert","wegen","höheren","verlustrisikos","häufig","teurer","banken","gesamtfinanzierung","gesondert","bewertet"]},{"kind":"lexicon","id":"nebenkostenabrechnung","title":"Nebenkostenabrechnung","category":"Immobilienkauf","summary":"Abrechnung umlagefähiger Betriebskosten gegenüber Mietern.","answer":"Abrechnung umlagefähiger Betriebskosten gegenüber Mietern. Die Nebenkostenabrechnung verteilt tatsächlich entstandene umlagefähige Betriebskosten auf den Mieter nach dem vereinbarten Schlüssel und rechnet Vorauszahlungen an. Formelle und materielle Fehler können Nachforderungen gefährden.","url":"/lexikon/nebenkostenabrechnung/","keywords":["nebenkostenabrechnung","abrechnung","umlagefähiger","betriebskosten","gegenüber","mietern","verteilt","tatsächlich","entstandene","umlagefähige","mieter","nach","vereinbarten","schlüssel","rechnet","vorauszahlungen","formelle","materielle","fehler","können","nachforderungen","gefährden"]},{"kind":"lexicon","id":"nettomietrendite","title":"Nettomietrendite","category":"Kapitalanlage","summary":"Jahresmiete abzüglich definierter Eigentümerkosten im Verhältnis zum Kaufpreis.","answer":"Jahresmiete abzüglich definierter Eigentümerkosten im Verhältnis zum Kaufpreis. Die Nettomietrendite berücksichtigt im Gegensatz zur Bruttomietrendite laufende Eigentümerkosten und sollte auf eine klar definierte Investitionsbasis bezogen werden. Unterschiedliche Marktquellen verwenden teils abweichende Definitionen.","url":"/lexikon/nettomietrendite/","keywords":["nettomietrendite","jahresmiete","abzüglich","definierter","eigentümerkosten","verhältnis","zum","kaufpreis","berücksichtigt","gegensatz","zur","bruttomietrendite","laufende","sollte","klar","definierte","investitionsbasis","bezogen","unterschiedliche","marktquellen","verwenden","teils","abweichende","definitionen"]},{"kind":"lexicon","id":"nettovermogen","title":"Nettovermögen","category":"Immobilienkauf","summary":"Vermögenswert abzüglich Verbindlichkeiten; Definition im Modell beachten.","answer":"Vermögenswert abzüglich Verbindlichkeiten; Definition im Modell beachten. Nettovermögen ist Vermögen abzüglich sämtlicher Verbindlichkeiten. Bei Immobilienvermögen ist deshalb nicht der Marktwert allein entscheidend, sondern Marktwert minus offene Darlehen und sonstige Schulden.","url":"/lexikon/nettovermogen/","keywords":["nettovermögen","vermögenswert","abzüglich","verbindlichkeiten","definition","modell","beachten","vermögen","sämtlicher","immobilienvermögen","deshalb","marktwert","allein","entscheidend","sondern","minus","offene","darlehen","sonstige","schulden"]},{"kind":"lexicon","id":"niebrauch","title":"Nießbrauch","category":"Immobilienkauf","summary":"Umfassendes Nutzungsrecht an einer Sache.","answer":"Umfassendes Nutzungsrecht an einer Sache. Nießbrauch gewährt dem Berechtigten typischerweise das Recht, die Nutzungen einer Sache zu ziehen, etwa selbst zu wohnen oder Mieten zu vereinnahmen. Ein eingetragener Nießbrauch kann Verkehrswert, Finanzierbarkeit und Verfügbarkeit für den Käufer stark beeinflussen.","url":"/lexikon/niebrauch/","keywords":["nießbrauch","umfassendes","nutzungsrecht","sache","gewährt","berechtigten","typischerweise","recht","nutzungen","ziehen","etwa","selbst","wohnen","mieten","vereinnahmen","ein","eingetragener","verkehrswert","finanzierbarkeit","verfügbarkeit","käufer","stark","beeinflussen"]},{"kind":"lexicon","id":"nominalrendite","title":"Nominalrendite","category":"Kapitalanlage","summary":"Rendite ohne Bereinigung um Inflation.","answer":"Rendite ohne Bereinigung um Inflation. Rendite ohne Bereinigung um Inflation. Nominalrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/nominalrendite/","keywords":["nominalrendite","rendite","ohne","bereinigung","inflation","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"nominalzins","title":"Nominalzins","category":"Finanzierung","summary":"Vertraglicher Zinssatz ohne weitere Kosten.","answer":"Vertraglicher Zinssatz ohne weitere Kosten. Nominalzins bezeichnet den vereinbarten Zinssatz ohne vollständige Einbeziehung sämtlicher preisbestimmender Kosten. Bei Verbraucherdarlehen ist für Angebotsvergleiche deshalb zusätzlich der effektive Jahreszins relevant.","url":"/lexikon/nominalzins/","keywords":["nominalzins","vertraglicher","zinssatz","ohne","weitere","kosten","bezeichnet","vereinbarten","vollständige","einbeziehung","sämtlicher","preisbestimmender","verbraucherdarlehen","angebotsvergleiche","deshalb","zusätzlich","effektive","jahreszins","relevant"]},{"kind":"lexicon","id":"objektrendite","title":"Objektrendite","category":"Kapitalanlage","summary":"Rendite des Objekts vor individueller Finanzierung.","answer":"Rendite des Objekts vor individueller Finanzierung. Rendite des Objekts vor individueller Finanzierung. Objektrendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/objektrendite/","keywords":["objektrendite","rendite","objekts","vor","individueller","finanzierung","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"operating-expenses","title":"Operating Expenses","category":"Immobilienkauf","summary":"Laufende Bewirtschaftungskosten.","answer":"Laufende Bewirtschaftungskosten. Operating Expenses (OpEx) sind laufende betriebliche Objektkosten. Welche Positionen enthalten sind, muss im jeweiligen Modell definiert werden; CapEx und Finanzierung werden regelmäßig getrennt betrachtet.","url":"/lexikon/operating-expenses/","keywords":["operating","expenses","laufende","bewirtschaftungskosten","opex","betriebliche","objektkosten","welche","positionen","enthalten","muss","jeweiligen","modell","definiert","capex","finanzierung","regelmäßig","getrennt","betrachtet"]},{"kind":"lexicon","id":"opportunitatskosten","title":"Opportunitätskosten","category":"Immobilienkauf","summary":"Entgangener Nutzen der besten nicht gewählten Alternative.","answer":"Entgangener Nutzen der besten nicht gewählten Alternative. Opportunitätskosten sind der entgangene Nutzen der besten nicht gewählten Alternative. Beim Eigenkapitaleinsatz zeigen sie, was gebundenes Kapital andernorts hätte erwirtschaften oder an Sicherheit bieten können.","url":"/lexikon/opportunitatskosten/","keywords":["opportunitätskosten","entgangener","nutzen","besten","gewählten","alternative","entgangene","beim","eigenkapitaleinsatz","zeigen","sie","was","gebundenes","kapital","andernorts","hätte","erwirtschaften","sicherheit","bieten","können"]},{"kind":"lexicon","id":"portfolio","title":"Portfolio","category":"Kapitalanlage","summary":"Gesamtheit mehrerer Investments.","answer":"Gesamtheit mehrerer Investments. Gesamtheit mehrerer Investments. Portfolio ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/portfolio/","keywords":["portfolio","gesamtheit","mehrerer","investments","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"preis-miet-verhaltnis","title":"Preis-Miet-Verhältnis","category":"Immobilienkauf","summary":"Kaufpreis relativ zum laufenden Mietniveau.","answer":"Kaufpreis relativ zum laufenden Mietniveau. Das Preis-Miet-Verhältnis beschreibt, wie hoch der Kaufpreis im Verhältnis zur Jahresmiete ist und entspricht bei gleicher Basis dem Kaufpreisfaktor. Es sagt nichts über Kosten, Finanzierung oder Zustand aus.","url":"/lexikon/preis-miet-verhaltnis/","keywords":["preis-miet-verhältnis","kaufpreis","relativ","zum","laufenden","mietniveau","beschreibt","wie","hoch","verhältnis","zur","jahresmiete","entspricht","gleicher","basis","kaufpreisfaktor","sagt","nichts","über","kosten","finanzierung","zustand","aus"]},{"kind":"lexicon","id":"prolongation","title":"Prolongation","category":"Finanzierung","summary":"Verlängerung einer Finanzierung beim bisherigen Kreditgeber.","answer":"Verlängerung einer Finanzierung beim bisherigen Kreditgeber. Prolongation ist die Verlängerung beziehungsweise Anschlussvereinbarung eines bestehenden Darlehens bei derselben Bank, meist für die Restschuld nach Zinsbindungsende.","url":"/lexikon/prolongation/","keywords":["prolongation","verlängerung","finanzierung","beim","bisherigen","kreditgeber","beziehungsweise","anschlussvereinbarung","bestehenden","darlehens","derselben","bank","meist","restschuld","nach","zinsbindungsende"]},{"kind":"lexicon","id":"reale-rendite","title":"Reale Rendite","category":"Kapitalanlage","summary":"Rendite nach Berücksichtigung der Inflation.","answer":"Rendite nach Berücksichtigung der Inflation. Rendite nach Berücksichtigung der Inflation. Reale Rendite ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/reale-rendite/","keywords":["reale","rendite","nach","berücksichtigung","inflation","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"restnutzungsdauer","title":"Restnutzungsdauer","category":"Immobilienkauf","summary":"Voraussichtliche verbleibende wirtschaftliche Nutzungsdauer.","answer":"Voraussichtliche verbleibende wirtschaftliche Nutzungsdauer. Die Restnutzungsdauer beschreibt den Zeitraum, in dem ein Gebäude voraussichtlich noch wirtschaftlich nutzbar ist. Sie ist in Bewertung und gegebenenfalls beim steuerlichen Nachweis einer kürzeren tatsächlichen Nutzungsdauer relevant.","url":"/lexikon/restnutzungsdauer/","keywords":["restnutzungsdauer","voraussichtliche","verbleibende","wirtschaftliche","nutzungsdauer","beschreibt","zeitraum","ein","gebäude","voraussichtlich","noch","wirtschaftlich","nutzbar","sie","bewertung","gegebenenfalls","beim","steuerlichen","nachweis","kürzeren","tatsächlichen","relevant"]},{"kind":"lexicon","id":"restschuld","title":"Restschuld","category":"Immobilienkauf","summary":"Noch nicht zurückgezahlter Darlehensbetrag.","answer":"Noch nicht zurückgezahlter Darlehensbetrag. Restschuld ist der nach geleisteten Tilgungen noch offene Darlehensbetrag. Sie bestimmt am Ende der Zinsbindung den Finanzierungsbedarf für die Anschlussfinanzierung.","url":"/lexikon/restschuld/","keywords":["restschuld","noch","zurückgezahlter","darlehensbetrag","nach","geleisteten","tilgungen","offene","sie","bestimmt","ende","zinsbindung","finanzierungsbedarf","anschlussfinanzierung"]},{"kind":"lexicon","id":"risikopuffer","title":"Risikopuffer","category":"Immobilienkauf","summary":"Konservativer Abschlag oder Zuschlag zur Abdeckung von Unsicherheit.","answer":"Konservativer Abschlag oder Zuschlag zur Abdeckung von Unsicherheit. Risikopuffer ist eine bewusst konservative Reserve in Geld oder Annahmen, um Unsicherheit abzudecken. Er sollte transparent ausgewiesen statt in mehreren versteckten Abschlägen doppelt berücksichtigt werden.","url":"/lexikon/risikopuffer/","keywords":["risikopuffer","konservativer","abschlag","zuschlag","zur","abdeckung","unsicherheit","bewusst","konservative","reserve","geld","annahmen","abzudecken","sollte","transparent","ausgewiesen","statt","mehreren","versteckten","abschlägen","doppelt","berücksichtigt"]},{"kind":"lexicon","id":"rucklage","title":"Rücklage","category":"Vermietung","summary":"Für künftige Ausgaben reservierte Mittel.","answer":"Für künftige Ausgaben reservierte Mittel. Rücklage ist ein zurückgehaltener Kapitalbetrag für zukünftige Ausgaben oder Risiken. Bei Immobilien muss zwischen privater Liquiditätsreserve und WEG-Erhaltungsrücklage unterschieden werden.","url":"/lexikon/rucklage/","keywords":["rücklage","künftige","ausgaben","reservierte","mittel","ein","zurückgehaltener","kapitalbetrag","zukünftige","risiken","immobilien","muss","zwischen","privater","liquiditätsreserve","weg-erhaltungsrücklage","unterschieden"]},{"kind":"lexicon","id":"sachwert","title":"Sachwert","category":"Immobilienkauf","summary":"Aus Herstellungskosten und Bodenwert abgeleiteter Wert.","answer":"Aus Herstellungskosten und Bodenwert abgeleiteter Wert. Sachwert ist ein im Sachwertverfahren abgeleiteter Immobilienwert aus Bodenwert und wertmäßigem Gebäude-/Anlagenbestand unter Marktanpassung. Er ist besonders bei eigennutzungsgeprägten Objekten relevant.","url":"/lexikon/sachwert/","keywords":["sachwert","aus","herstellungskosten","bodenwert","abgeleiteter","wert","ein","sachwertverfahren","immobilienwert","wertmäßigem","gebäude-","anlagenbestand","unter","marktanpassung","besonders","eigennutzungsgeprägten","objekten","relevant"]},{"kind":"lexicon","id":"sondereigentum","title":"Sondereigentum","category":"Immobilienkauf","summary":"Alleineigentum an bestimmten Räumen einer WEG.","answer":"Alleineigentum an bestimmten Räumen einer WEG. Sondereigentum ist das dem einzelnen Wohnungseigentümer allein zugeordnete Eigentum an bestimmten Räumen und Bestandteilen. Tragende Teile und viele gemeinschaftlich dienende Bauteile bleiben Gemeinschaftseigentum.","url":"/lexikon/sondereigentum/","keywords":["sondereigentum","alleineigentum","bestimmten","räumen","weg","einzelnen","wohnungseigentümer","allein","zugeordnete","eigentum","bestandteilen","tragende","teile","viele","gemeinschaftlich","dienende","bauteile","bleiben","gemeinschaftseigentum"]},{"kind":"lexicon","id":"sondertilgung","title":"Sondertilgung","category":"Finanzierung","summary":"Zusätzliche Tilgung außerhalb der regulären Rate.","answer":"Zusätzliche Tilgung außerhalb der regulären Rate. Sondertilgung ist eine zusätzliche außerplanmäßige Tilgung außerhalb der regulären Rate, soweit der Darlehensvertrag dies erlaubt. Sie reduziert Restschuld und zukünftige Zinsbelastung, bindet aber Liquidität.","url":"/lexikon/sondertilgung/","keywords":["sondertilgung","zusätzliche","tilgung","außerhalb","regulären","rate","außerplanmäßige","soweit","darlehensvertrag","dies","erlaubt","sie","reduziert","restschuld","zukünftige","zinsbelastung","bindet","aber","liquidität"]},{"kind":"lexicon","id":"sonderumlage","title":"Sonderumlage","category":"Vermietung","summary":"Zusätzliche Zahlung der Wohnungseigentümer aufgrund eines WEG-Beschlusses.","answer":"Zusätzliche Zahlung der Wohnungseigentümer aufgrund eines WEG-Beschlusses. Eine Sonderumlage ist ein zusätzlicher Finanzierungsbeitrag der Wohnungseigentümer, wenn laufende Mittel und Rücklage nicht ausreichen. Für Käufer sind sowohl bereits beschlossene Umlagen als auch aus Protokollen erkennbare größere Maßnahmen wirtschaftlich relevant.","url":"/lexikon/sonderumlage/","keywords":["sonderumlage","zusätzliche","zahlung","wohnungseigentümer","aufgrund","weg-beschlusses","ein","zusätzlicher","finanzierungsbeitrag","wenn","laufende","mittel","rücklage","ausreichen","käufer","sowohl","bereits","beschlossene","umlagen","aus","protokollen","erkennbare","größere","maßnahmen","wirtschaftlich","relevant"]},{"kind":"lexicon","id":"spekulationsfrist","title":"Spekulationsfrist","category":"Steuern","summary":"Umgangssprachliche Bezeichnung für steuerlich relevante Haltefristen.","answer":"Umgangssprachliche Bezeichnung für steuerlich relevante Haltefristen. Die sogenannte Spekulationsfrist bezeichnet im Privatvermögen die Zehnjahresfrist des § 23 EStG für private Grundstücksveräußerungsgeschäfte; für bestimmte Eigennutzungsfälle gelten Ausnahmen. Bei Betriebsvermögen oder gewerblichem Grundstückshandel greifen andere Regeln.","url":"/lexikon/spekulationsfrist/","keywords":["spekulationsfrist","umgangssprachliche","bezeichnung","steuerlich","relevante","haltefristen","sogenannte","bezeichnet","privatvermögen","zehnjahresfrist","estg","private","grundstücksveräußerungsgeschäfte","bestimmte","eigennutzungsfälle","gelten","ausnahmen","betriebsvermögen","gewerblichem","grundstückshandel","greifen","andere","regeln"]},{"kind":"lexicon","id":"staffelmiete","title":"Staffelmiete","category":"Vermietung","summary":"Miete mit im Voraus vereinbarten Erhöhungsbeträgen.","answer":"Miete mit im Voraus vereinbarten Erhöhungsbeträgen. Bei der Staffelmiete werden zukünftige Mietbeträge beziehungsweise Erhöhungen bereits im Vertrag als Geldbetrag festgelegt. Zwischen den Staffeln muss die Miete jeweils mindestens ein Jahr unverändert bleiben.","url":"/lexikon/staffelmiete/","keywords":["staffelmiete","miete","voraus","vereinbarten","erhöhungsbeträgen","zukünftige","mietbeträge","beziehungsweise","erhöhungen","bereits","vertrag","geldbetrag","festgelegt","zwischen","staffeln","muss","jeweils","mindestens","ein","jahr","unverändert","bleiben"]},{"kind":"lexicon","id":"steuerlicher-uberschuss","title":"Steuerlicher Überschuss","category":"Steuern","summary":"Steuerlich ermittelte Einkünfte nach abzugsfähigen Aufwendungen.","answer":"Steuerlich ermittelte Einkünfte nach abzugsfähigen Aufwendungen. Der steuerliche Überschuss aus Vermietung ergibt sich vereinfacht aus steuerpflichtigen Einnahmen minus abzugsfähigen Werbungskosten. Er unterscheidet sich vom Cashflow, weil AfA und Tilgung unterschiedlich behandelt werden.","url":"/lexikon/steuerlicher-uberschuss/","keywords":["steuerlicher","überschuss","steuerlich","ermittelte","einkünfte","nach","abzugsfähigen","aufwendungen","steuerliche","aus","vermietung","ergibt","vereinfacht","steuerpflichtigen","einnahmen","minus","werbungskosten","unterscheidet","vom","cashflow","weil","afa","tilgung","unterschiedlich","behandelt"]},{"kind":"lexicon","id":"stress-test","title":"Stress-Test","category":"Immobilienkauf","summary":"Berechnung unter ungünstigeren Annahmen.","answer":"Berechnung unter ungünstigeren Annahmen. Ein Stress-Test prüft die Tragfähigkeit unter bewusst verschlechterten Annahmen, etwa höherem Zins, Leerstand oder CapEx. Er unterscheidet sich von einer einfachen Sensitivität, weil mehrere Belastungen gleichzeitig kombiniert werden können.","url":"/lexikon/stress-test/","keywords":["stress-test","berechnung","unter","ungünstigeren","annahmen","ein","prüft","tragfähigkeit","bewusst","verschlechterten","etwa","höherem","zins","leerstand","capex","unterscheidet","einfachen","sensitivität","weil","mehrere","belastungen","gleichzeitig","kombiniert","können"]},{"kind":"lexicon","id":"teilungserklarung","title":"Teilungserklärung","category":"Immobilienkauf","summary":"Dokument zur Aufteilung eines Grundstücks in Wohnungs- oder Teileigentum.","answer":"Dokument zur Aufteilung eines Grundstücks in Wohnungs- oder Teileigentum. Die Teilungserklärung legt bei Wohnungseigentum die Aufteilung in Sonder- und Gemeinschaftseigentum sowie Miteigentumsanteile und häufig Nutzungs-/Kostenregelungen fest. Sie ist eine zentrale Rechtsgrundlage der ETW-Prüfung.","url":"/lexikon/teilungserklarung/","keywords":["teilungserklärung","dokument","zur","aufteilung","grundstücks","wohnungs-","teileigentum","legt","wohnungseigentum","sonder-","gemeinschaftseigentum","sowie","miteigentumsanteile","häufig","nutzungs-","kostenregelungen","fest","sie","zentrale","rechtsgrundlage","etw-prüfung"]},{"kind":"lexicon","id":"tilgung","title":"Tilgung","category":"Finanzierung","summary":"Rückzahlung des Darlehenskapitals.","answer":"Rückzahlung des Darlehenskapitals. Tilgung ist die Rückzahlung des Darlehenskapitals. Im Annuitätendarlehen steigt der Tilgungsanteil innerhalb der konstanten Rate, weil der Zinsanteil mit sinkender Restschuld abnimmt.","url":"/lexikon/tilgung/","keywords":["tilgung","rückzahlung","darlehenskapitals","annuitätendarlehen","steigt","tilgungsanteil","innerhalb","konstanten","rate","weil","zinsanteil","sinkender","restschuld","abnimmt"]},{"kind":"lexicon","id":"tilgungssatz","title":"Tilgungssatz","category":"Finanzierung","summary":"Anfänglicher oder laufender Anteil der Darlehensrückzahlung.","answer":"Anfänglicher oder laufender Anteil der Darlehensrückzahlung. Der Tilgungssatz beschreibt den anfänglichen jährlichen Kapitalrückzahlungsanteil bezogen auf die Darlehenssumme. Im Annuitätendarlehen steigt der tatsächliche Tilgungsanteil im Zeitverlauf.","url":"/lexikon/tilgungssatz/","keywords":["tilgungssatz","anfänglicher","laufender","anteil","darlehensrückzahlung","beschreibt","anfänglichen","jährlichen","kapitalrückzahlungsanteil","bezogen","darlehenssumme","annuitätendarlehen","steigt","tatsächliche","tilgungsanteil","zeitverlauf"]},{"kind":"lexicon","id":"total-return","title":"Total Return","category":"Kapitalanlage","summary":"Gesamtertrag aus laufenden Zahlungen und Wertveränderung.","answer":"Gesamtertrag aus laufenden Zahlungen und Wertveränderung. Gesamtertrag aus laufenden Zahlungen und Wertveränderung. Total Return ist eine Investmentkennzahl bzw. Risikogröße. Für Vergleiche müssen Definition, Zeitraum und einbezogene Kosten identisch sein.","url":"/lexikon/total-return/","keywords":["total","return","gesamtertrag","aus","laufenden","zahlungen","wertveränderung","investmentkennzahl","bzw","risikogröße","vergleiche","müssen","definition","zeitraum","einbezogene","kosten","identisch","sein"]},{"kind":"lexicon","id":"transaktionskosten","title":"Transaktionskosten","category":"Immobilienkauf","summary":"Kosten, die durch Erwerb oder Verkauf entstehen.","answer":"Kosten, die durch Erwerb oder Verkauf entstehen. Transaktionskosten sind Kosten für Erwerb, Finanzierung, Halten oder Verkauf, die zusätzlich zum reinen Vermögenswert entstehen. Sie beeinflussen besonders die Rendite kurzer Haltedauern.","url":"/lexikon/transaktionskosten/","keywords":["transaktionskosten","kosten","durch","erwerb","verkauf","entstehen","finanzierung","halten","zusätzlich","zum","reinen","vermögenswert","sie","beeinflussen","besonders","rendite","kurzer","haltedauern"]},{"kind":"lexicon","id":"umlagefahige-kosten","title":"Umlagefähige Kosten","category":"Vermietung","summary":"Betriebskosten, die bei wirksamer Vereinbarung auf Mieter umgelegt werden können.","answer":"Betriebskosten, die bei wirksamer Vereinbarung auf Mieter umgelegt werden können. Umlagefähige Kosten sind Betriebskosten, die nach Gesetz und Mietvertrag auf den Mieter verteilt werden dürfen. Umlagefähigkeit bedeutet nicht, dass der Eigentümer kein Leerstands- oder Ausfallrisiko trägt.","url":"/lexikon/umlagefahige-kosten/","keywords":["umlagefähige","kosten","betriebskosten","wirksamer","vereinbarung","mieter","umgelegt","können","nach","gesetz","mietvertrag","verteilt","dürfen","umlagefähigkeit","bedeutet","dass","eigentümer","kein","leerstands-","ausfallrisiko","trägt"]},{"kind":"lexicon","id":"umwandlung","title":"Umwandlung","category":"Immobilienkauf","summary":"Aufteilung eines Mietshauses in Wohnungseigentum.","answer":"Aufteilung eines Mietshauses in Wohnungseigentum. Umwandlung bezeichnet im Immobilienkontext häufig die Aufteilung eines Mietshauses in Wohnungseigentum. Sie kann genehmigungs-, miet- und milieuschutzrechtliche Besonderheiten auslösen.","url":"/lexikon/umwandlung/","keywords":["umwandlung","aufteilung","mietshauses","wohnungseigentum","bezeichnet","immobilienkontext","häufig","sie","genehmigungs-","miet-","milieuschutzrechtliche","besonderheiten","auslösen"]},{"kind":"lexicon","id":"unterdeckung","title":"Unterdeckung","category":"Immobilienkauf","summary":"Situation, in der Erlös oder Wert die Verbindlichkeiten nicht deckt.","answer":"Situation, in der Erlös oder Wert die Verbindlichkeiten nicht deckt. Unterdeckung liegt vor, wenn vorhandene Mittel oder Erlöse eine Verpflichtung nicht vollständig decken. Bei Immobilien kann sie etwa entstehen, wenn Verkaufserlös nach Kosten unter der offenen Darlehensschuld liegt.","url":"/lexikon/unterdeckung/","keywords":["unterdeckung","situation","erlös","wert","verbindlichkeiten","deckt","liegt","vor","wenn","vorhandene","mittel","erlöse","verpflichtung","vollständig","decken","immobilien","sie","etwa","entstehen","verkaufserlös","nach","kosten","unter","offenen","darlehensschuld"]},{"kind":"lexicon","id":"verkehrswert","title":"Verkehrswert","category":"Immobilienkauf","summary":"Marktwert nach den gesetzlichen Bewertungsgrundsätzen.","answer":"Marktwert nach den gesetzlichen Bewertungsgrundsätzen. Verkehrswert beziehungsweise Marktwert ist nach § 194 BauGB der Preis, der im gewöhnlichen Geschäftsverkehr unter Berücksichtigung der rechtlichen Gegebenheiten, tatsächlichen Eigenschaften und Lage ohne ungewöhnliche oder persönliche Verhältnisse erzielbar wäre.","url":"/lexikon/verkehrswert/","keywords":["verkehrswert","marktwert","nach","gesetzlichen","bewertungsgrundsätzen","beziehungsweise","194","baugb","preis","gewöhnlichen","geschäftsverkehr","unter","berücksichtigung","rechtlichen","gegebenheiten","tatsächlichen","eigenschaften","lage","ohne","ungewöhnliche","persönliche","verhältnisse","erzielbar","wäre"]},{"kind":"lexicon","id":"vervielfaltiger","title":"Vervielfältiger","category":"Immobilienkauf","summary":"Synonym für Kaufpreisfaktor.","answer":"Synonym für Kaufpreisfaktor. Vervielfältiger wird im Immobilienmarkt häufig synonym für Kaufpreisfaktor verwendet; in Bewertungsverfahren kann „Vervielfältiger“ auch einen mathematischen Kapitalisierungsfaktor bezeichnen. Der Kontext muss deshalb klar sein.","url":"/lexikon/vervielfaltiger/","keywords":["vervielfältiger","synonym","kaufpreisfaktor","immobilienmarkt","häufig","verwendet","bewertungsverfahren","einen","mathematischen","kapitalisierungsfaktor","bezeichnen","kontext","muss","deshalb","klar","sein"]},{"kind":"lexicon","id":"verwaltungskosten","title":"Verwaltungskosten","category":"Immobilienkauf","summary":"Kosten der kaufmännischen und technischen Verwaltung.","answer":"Kosten der kaufmännischen und technischen Verwaltung. Verwaltungskosten entstehen für kaufmännische und technische Verwaltung. Bei Wohnraummiete sind sie grundsätzlich nicht als Betriebskosten auf den Mieter umlagefähig und verbleiben daher in der Eigentümerrechnung.","url":"/lexikon/verwaltungskosten/","keywords":["verwaltungskosten","kosten","kaufmännischen","technischen","verwaltung","entstehen","kaufmännische","technische","wohnraummiete","sie","grundsätzlich","betriebskosten","mieter","umlagefähig","verbleiben","daher","eigentümerrechnung"]},{"kind":"lexicon","id":"vollfinanzierung","title":"Vollfinanzierung","category":"Finanzierung","summary":"Finanzierung des Kaufpreises ohne Eigenkapitalanteil am Kaufpreis.","answer":"Finanzierung des Kaufpreises ohne Eigenkapitalanteil am Kaufpreis. Vollfinanzierung bedeutet regelmäßig, dass der Kaufpreis vollständig fremdfinanziert wird. Eine Finanzierung zusätzlich der Erwerbsnebenkosten wird häufig als 110-%-Finanzierung bezeichnet. Die höhere Fremdfinanzierung kann Zins und Unterdeckungsrisiko erhöhen.","url":"/lexikon/vollfinanzierung/","keywords":["vollfinanzierung","finanzierung","kaufpreises","ohne","eigenkapitalanteil","kaufpreis","bedeutet","regelmäßig","dass","vollständig","fremdfinanziert","zusätzlich","erwerbsnebenkosten","häufig","110-%-finanzierung","bezeichnet","höhere","fremdfinanzierung","zins","unterdeckungsrisiko","erhöhen"]},{"kind":"lexicon","id":"vorfalligkeitsentschadigung","title":"Vorfälligkeitsentschädigung","category":"Immobilienkauf","summary":"Möglicher Ausgleich der Bank bei vorzeitiger Darlehensablösung.","answer":"Möglicher Ausgleich der Bank bei vorzeitiger Darlehensablösung. Eine Vorfälligkeitsentschädigung kann bei vorzeitiger Rückzahlung eines fest verzinsten Darlehens entstehen, wenn der Bank ein rechtlich ersatzfähiger Zinsschaden entsteht. Ob und in welcher Höhe sie anfällt, hängt vom Vertrag und gesetzlichen Kündigungs-/Berechnungsregeln ab.","url":"/lexikon/vorfalligkeitsentschadigung/","keywords":["vorfälligkeitsentschädigung","möglicher","ausgleich","bank","vorzeitiger","darlehensablösung","rückzahlung","fest","verzinsten","darlehens","entstehen","wenn","ein","rechtlich","ersatzfähiger","zinsschaden","entsteht","welcher","höhe","sie","anfällt","hängt","vom","vertrag","gesetzlichen","kündigungs-","berechnungsregeln"]},{"kind":"lexicon","id":"weg","title":"WEG","category":"Vermietung","summary":"Wohnungseigentümergemeinschaft.","answer":"Wohnungseigentümergemeinschaft. WEG bezeichnet je nach Kontext das Wohnungseigentumsgesetz oder die Gemeinschaft der Wohnungseigentümer. Für ETW-Investoren sind Beschlüsse, Kostenverteilung, Rücklagen und Zustand des Gemeinschaftseigentums zentrale Risikofaktoren.","url":"/lexikon/weg/","keywords":["weg","wohnungseigentümergemeinschaft","bezeichnet","nach","kontext","wohnungseigentumsgesetz","gemeinschaft","wohnungseigentümer","etw-investoren","beschlüsse","kostenverteilung","rücklagen","zustand","gemeinschaftseigentums","zentrale","risikofaktoren"]},{"kind":"lexicon","id":"werbungskosten","title":"Werbungskosten","category":"Steuern","summary":"Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen.","answer":"Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen. Werbungskosten sind Aufwendungen zur Erwerbung, Sicherung und Erhaltung steuerpflichtiger Einnahmen. Bei Vermietung können dazu je nach Sachverhalt etwa Schuldzinsen, Verwaltung oder bestimmte Erhaltungsaufwendungen gehören; Tilgung zählt nicht dazu.","url":"/lexikon/werbungskosten/","keywords":["werbungskosten","aufwendungen","zur","erwerbung","sicherung","erhaltung","steuerpflichtiger","einnahmen","vermietung","können","dazu","nach","sachverhalt","etwa","schuldzinsen","verwaltung","bestimmte","erhaltungsaufwendungen","gehören","tilgung","zählt"]},{"kind":"lexicon","id":"wertsteigerung","title":"Wertsteigerung","category":"Immobilienkauf","summary":"Zunahme des Marktwerts; keine garantierte Größe.","answer":"Zunahme des Marktwerts; keine garantierte Größe. Wertsteigerung ist die Zunahme des Marktwerts über die Zeit. Sie ist kein garantierter Cashflow und sollte in Investmentrechnungen als Szenario statt als sichere Renditekomponente behandelt werden.","url":"/lexikon/wertsteigerung/","keywords":["wertsteigerung","zunahme","marktwerts","keine","garantierte","größe","über","zeit","sie","kein","garantierter","cashflow","sollte","investmentrechnungen","szenario","statt","sichere","renditekomponente","behandelt"]},{"kind":"lexicon","id":"wirtschaftsplan","title":"Wirtschaftsplan","category":"Immobilienkauf","summary":"Plan der WEG zu Einnahmen, Ausgaben und Vorschüssen.","answer":"Plan der WEG zu Einnahmen, Ausgaben und Vorschüssen. Der Wirtschaftsplan der WEG enthält die voraussichtlichen Einnahmen/Ausgaben und Vorschüsse der Eigentümer. Für Kapitalanleger ist die Aufteilung in umlagefähige Kosten, nicht umlagefähige Kosten und Rücklagenzuführung entscheidend.","url":"/lexikon/wirtschaftsplan/","keywords":["wirtschaftsplan","plan","weg","einnahmen","ausgaben","vorschüssen","enthält","voraussichtlichen","vorschüsse","eigentümer","kapitalanleger","aufteilung","umlagefähige","kosten","rücklagenzuführung","entscheidend"]},{"kind":"lexicon","id":"wohnflache","title":"Wohnfläche","category":"Immobilienkauf","summary":"Nach einem Regelwerk ermittelte anrechenbare Fläche.","answer":"Nach einem Regelwerk ermittelte anrechenbare Fläche. Wohnfläche ist die nach dem anwendbaren Regelwerk anrechenbare Fläche einer Wohnung. Nach WoFlV zählen unter anderem Keller/Garagen grundsätzlich nicht; Balkone/Terrassen werden regelmäßig nur anteilig und Dachschrägen abhängig von der lichten Höhe berücksichtigt.","url":"/lexikon/wohnflache/","keywords":["wohnfläche","nach","einem","regelwerk","ermittelte","anrechenbare","fläche","anwendbaren","wohnung","woflv","zählen","unter","anderem","keller","garagen","grundsätzlich","balkone","terrassen","regelmäßig","nur","anteilig","dachschrägen","abhängig","lichten","höhe","berücksichtigt"]},{"kind":"lexicon","id":"wohnrecht","title":"Wohnrecht","category":"Immobilienkauf","summary":"Recht, Räume zu Wohnzwecken zu nutzen.","answer":"Recht, Räume zu Wohnzwecken zu nutzen. Ein dingliches Wohnrecht sichert dem Berechtigten die Nutzung bestimmter Räume. Es kann den wirtschaftlichen Wert und die freie Verfügbarkeit einer Immobilie erheblich einschränken.","url":"/lexikon/wohnrecht/","keywords":["wohnrecht","recht","räume","wohnzwecken","nutzen","ein","dingliches","sichert","berechtigten","nutzung","bestimmter","wirtschaftlichen","wert","freie","verfügbarkeit","immobilie","erheblich","einschränken"]},{"kind":"lexicon","id":"zins","title":"Zins","category":"Finanzierung","summary":"Preis für die zeitweise Überlassung von Kapital.","answer":"Preis für die zeitweise Überlassung von Kapital. Zins ist der Preis für die zeitweise Überlassung von Kapital. Bei Immobilienfinanzierungen ist zwischen Sollzins, effektivem Jahreszins, Zinsbindung und tatsächlicher Zinsbelastung auf die fallende Restschuld zu unterscheiden.","url":"/lexikon/zins/","keywords":["zins","preis","zeitweise","überlassung","kapital","immobilienfinanzierungen","zwischen","sollzins","effektivem","jahreszins","zinsbindung","tatsächlicher","zinsbelastung","fallende","restschuld","unterscheiden"]},{"kind":"lexicon","id":"zinsbindung","title":"Zinsbindung","category":"Finanzierung","summary":"Zeitraum, für den der Sollzins fest vereinbart ist.","answer":"Zeitraum, für den der Sollzins fest vereinbart ist. Die Zinsbindung ist der Zeitraum, in dem der vereinbarte Sollzins unverändert gilt. Eine längere Bindung erhöht Planungssicherheit, kann aber einen höheren Anfangszins bedeuten.","url":"/lexikon/zinsbindung/","keywords":["zinsbindung","zeitraum","sollzins","fest","vereinbart","vereinbarte","unverändert","gilt","längere","bindung","erhöht","planungssicherheit","aber","einen","höheren","anfangszins","bedeuten"]},{"kind":"lexicon","id":"zinsdeckungsgrad","title":"Zinsdeckungsgrad","category":"Finanzierung","summary":"Verhältnis von Ergebnisgröße zu Zinsaufwand.","answer":"Verhältnis von Ergebnisgröße zu Zinsaufwand. Der Zinsdeckungsgrad misst, wie oft eine definierte Ergebnisgröße den reinen Zinsaufwand deckt. Anders als der DSCR berücksichtigt er typischerweise nicht die Tilgung.","url":"/lexikon/zinsdeckungsgrad/","keywords":["zinsdeckungsgrad","verhältnis","ergebnisgröße","zinsaufwand","misst","wie","oft","definierte","reinen","deckt","anders","dscr","berücksichtigt","typischerweise","tilgung"]},{"kind":"lexicon","id":"zinseszins","title":"Zinseszins","category":"Finanzierung","summary":"Verzinsung bereits gutgeschriebener Zinsen.","answer":"Verzinsung bereits gutgeschriebener Zinsen. Zinseszins entsteht, wenn nicht nur das Anfangskapital, sondern auch bereits gutgeschriebene Zinsen weiter verzinst werden. Er ist besonders bei langfristigem Vermögensaufbau und Opportunitätskosten relevant.","url":"/lexikon/zinseszins/","keywords":["zinseszins","verzinsung","bereits","gutgeschriebener","zinsen","entsteht","wenn","nur","anfangskapital","sondern","gutgeschriebene","weiter","verzinst","besonders","langfristigem","vermögensaufbau","opportunitätskosten","relevant"]},{"kind":"lexicon","id":"zinsanderungsrisiko","title":"Zinsänderungsrisiko","category":"Finanzierung","summary":"Risiko höherer Kosten bei künftiger Zinsanpassung.","answer":"Risiko höherer Kosten bei künftiger Zinsanpassung. Zinsänderungsrisiko ist das Risiko, dass die Anschlussfinanzierung nach Ende der Zinsbindung zu höheren Konditionen erfolgt. Maßgeblich ist die Restschuld zum Anschlusszeitpunkt.","url":"/lexikon/zinsanderungsrisiko/","keywords":["zinsänderungsrisiko","risiko","höherer","kosten","künftiger","zinsanpassung","dass","anschlussfinanzierung","nach","ende","zinsbindung","höheren","konditionen","erfolgt","maßgeblich","restschuld","zum","anschlusszeitpunkt"]},{"kind":"lexicon","id":"zwangsversteigerung","title":"Zwangsversteigerung","category":"Immobilienkauf","summary":"Gerichtliches Verfahren zur Verwertung einer Immobilie.","answer":"Gerichtliches Verfahren zur Verwertung einer Immobilie. Zwangsversteigerung ist ein gerichtliches Verwertungsverfahren. Erwerber müssen Gutachten, Grundbuch, bestehenbleibende Rechte, Sicherheitsleistung und eingeschränkte Gewährleistung besonders sorgfältig prüfen.","url":"/lexikon/zwangsversteigerung/","keywords":["zwangsversteigerung","gerichtliches","verfahren","zur","verwertung","immobilie","ein","verwertungsverfahren","erwerber","müssen","gutachten","grundbuch","bestehenbleibende","rechte","sicherheitsleistung","eingeschränkte","gewährleistung","besonders","sorgfältig","prüfen"]},{"kind":"lexicon","id":"zweckentfremdung","title":"Zweckentfremdung","category":"Immobilienkauf","summary":"Nutzung von Wohnraum zu anderen als Wohnzwecken unter rechtlichen Einschränkungen.","answer":"Nutzung von Wohnraum zu anderen als Wohnzwecken unter rechtlichen Einschränkungen. Zweckentfremdung bezeichnet die Nutzung von Wohnraum zu anderen Zwecken, etwa gewerblicher Kurzzeitvermietung, wenn lokale Vorschriften dies beschränken oder genehmigungspflichtig machen. Regelungen sind kommunal beziehungsweise landesrechtlich unterschiedlich.","url":"/lexikon/zweckentfremdung/","keywords":["zweckentfremdung","nutzung","wohnraum","anderen","wohnzwecken","unter","rechtlichen","einschränkungen","bezeichnet","zwecken","etwa","gewerblicher","kurzzeitvermietung","wenn","lokale","vorschriften","dies","beschränken","genehmigungspflichtig","machen","regelungen","kommunal","beziehungsweise","landesrechtlich","unterschiedlich"]}];
